def _opt(values: list[str], selected: str | None) -> str:
    out = ['<option value=""></option>']
    vals = list(values)
    if selected and selected not in vals:
        vals = [selected] + vals  # マスタ外の現値も必ず表示（例: 旧/失注ステージ）
    for v in vals:
        sel = " selected" if v == selected else ""
        out.append(f'<option value="{html.escape(v)}"{sel}>{html.escape(v)}</option>')
    return "".join(out)


def _opt_kv(pairs: list[tuple[str, str]], selected: str | None) -> str:
    """(value, label) ペアリストから select options を生成。"""
    out = ['<option value=""></option>']
    for v, label in pairs:
        sel = " selected" if v == selected else ""
        out.append(f'<option value="{html.escape(v)}"{sel}>{html.escape(label)}</option>')
    return "".join(out)


def _esc(v) -> str:
    return "" if v is None else html.escape(str(v))


def _is_float_str(v) -> bool:
    try:
        float(v)
        return True
    except (TypeError, ValueError):
        return False


def _num(v, default=0) -> float:
    """外部入力由来の値を数値に強制する（HTML/SVGへ埋め込む前のXSS・型事故防止）。"""
    if isinstance(v, (int, float)):
        return v
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def _csv_safe(v):
    """CSVセル値の数式インジェクション中和。=+-@ 等で始まる文字列はExcel/Sheetsで
    数式として実行されうるため、先頭にシングルクォートを付けて無害化する。"""
    if isinstance(v, str) and v and v[0] in ("=", "+", "-", "@", "\t", "\r"):
        return "'" + v
    return v


def _opt_l2(con, l1: str | None, selected: str | None) -> str:
    """L1に対応するL2選択肢を生成（マスタのツリーを参照）。"""
    opts = ['<option value=""></option>']
    for v in sfa_db.business_type_l2_of(con, l1):
        sel = " selected" if v == selected else ""
        opts.append(f'<option value="{html.escape(v)}"{sel}>{html.escape(v)}</option>')
    return "".join(opts)


def _decode_uploaded_csv(file_item) -> str | None:
    """CSV一括取込のファイルアップロード欄（multipart）から取得したバイト列をCSVテキストにする。

    - .xlsx/.xlsは csv_utils.xlsx_to_csv_text() でセル座標ベースに変換する
      （名刺xlsxアップロードは別の固定列レイアウト専用なので、テンプレート形式の
      xlsxをそちらに誤ってアップロードすると列がズレて壊れる。こちらの欄で
      xlsxも直接受け付けることで、その事故を防ぐ）。
    - .csv等のテキストファイルはUTF-8(BOM可)を試し、失敗したらcp932にフォールバック
      （Excel日本語Windowsの「CSV(カンマ区切り)」保存はShift-JISになることが多いため）。
    """
    if not file_item or not isinstance(file_item, tuple):
        return None
    filename, data = file_item
    if not data:
        return None
    if (filename or "").lower().endswith((".xlsx", ".xls")):
        try:
            return csv_utils.xlsx_to_csv_text(data)
        except Exception:
            return None
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        return data.decode("cp932", errors="replace")


def _sticky_th(label: str, width: str | None = None) -> str:
    """縦スクロールしても項目名が見えるよう、テーブル見出しをposition:stickyにする共通ヘルパー。
    親のoverflow:auto付きコンテナ内で使うこと（テーブル単体ではスクロールしないため効果がない）。"""
    w = f' style="width:{width}"' if width else ""
    return f'<th class="sticky"{w}>{label}</th>'


def _call_claude_haiku(prompt: str, *, timeout: int = 20, max_wait: int = 25,
                       max_tokens: int = 512) -> str:
    """Claude Haikuを呼び出しテキストを返す。APIキー未設定・失敗・タイムアウト時は空文字。
    max_tokens は用途に応じて指定（要約=既定512／構造化整形など長い出力=2000〜4000を推奨）。"""
    if not ANTHROPIC_API_KEY:
        return ""
    result: list = [None]

    def _do():
        try:
            payload = json.dumps({
                "model": "claude-haiku-4-5-20251001",
                "max_tokens": max_tokens,
                "messages": [{"role": "user", "content": prompt}],
            }).encode()
            req = urllib.request.Request(
                "https://api.anthropic.com/v1/messages", data=payload, headers={
                    "x-api-key": ANTHROPIC_API_KEY,
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                })
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                body = json.loads(resp.read())
            result[0] = body["content"][0]["text"].strip()
        except Exception as e:
            print(f"[issue AI summary] Claude API error: {e}", flush=True)

    t = threading.Thread(target=_do, daemon=True)
    t.start()
    t.join(timeout=max_wait)
    return result[0] or ""


def _generate_issue_ai_summary(issue: dict, notes_text: str) -> str:
    """論点メモ(rich_notes)の全文からAIサマリーを生成する。失敗時は空文字（呼び出し側は既存サマリーを保持すること）。"""
    if not (notes_text or "").strip():
        return ""
    prompt = (
        f"以下は社内論点「{issue.get('issue','')}」についての論点メモです。\n"
        "話されているサブトピック・論点ごとに分けて、日本語で箇条書きに要約してください。\n"
        "各行は必ず「・トピック名：内容」の形式で書いてください"
        "（トピック名は名詞句で2〜10文字程度の短い見出し、内容にできれば結論や合意事項が分かるように書く）。\n"
        "まだ結論が出ていない・保留中の論点があれば、そのように分かるように書いてください。\n"
        "箇条書きは最大6行程度、前置きや「要約:」等の言葉は不要で、箇条書き本文だけを出力してください。\n\n"
        f"{notes_text}"
    )
    return _call_claude_haiku(prompt)


def _issue_notes_text(con, issue_id: int) -> str:
    """論点メモ(rich_notes kind='issue')の全ノートをタグ除去した平文で連結する（AIサマリ生成の入力）。"""
    parts = []
    for n in sfa_db.list_rich_notes(con, "issue", issue_id):
        title = (n.get("title") or "").strip()
        body = re.sub(r"<[^>]+>", "\n", n.get("body") or "")   # ブロック境界を改行に
        body = html.unescape(body)
        body = re.sub(r"[ \t]+\n", "\n", body)
        body = re.sub(r"\n{3,}", "\n\n", body).strip()
        if title or body:
            parts.append((f"# {title}\n" if title else "") + body)
    return "\n\n".join(parts).strip()


# ── 社内資料の体系化・層2(検討資料)生成（2026-08-28） ──────────────────────
# 層1(issue_materials＋論点メモ)を材料に、AIが「型」に沿って構造化生成する。型（見出し構成・
# 順序）はこちらのコード側で固定し、AIには各見出しの中身だけを埋めさせることで、生成のたびに
# 構成が崩れない（ユーザー要望: 一定の型・骨子を外さない構成に制御）。
_DOC_TEMPLATE_SECTIONS = {
    "process_change": [
        ("background", "背景・課題認識"),
        ("problem", "現状の問題点"),
        ("proposal", "提案内容"),
        ("effect", "期待される効果"),
        ("plan", "実行計画（スケジュール・担当）"),
        ("risk", "リスク・懸念事項"),
        ("decision", "意思決定を求める事項"),
    ],
}
_DOC_TEMPLATE_LABELS = {"process_change": "業務改善・社内プロセス変更提案資料"}


def _issue_materials_text(con, issue_id: int) -> str:
    """検討材料(issue_materials)の全文を連結する（層2生成の入力）。"""
    parts = []
    for m in sfa_db.list_issue_materials(con, issue_id):
        title = (m.get("title") or "").strip()
        content = (m.get("content") or "").strip()
        if content:
            parts.append((f"# {title}\n" if title else "") + content)
    return "\n\n".join(parts).strip()


def _parse_doc_sections(raw: str, headings: list) -> dict:
    """AIの生の出力を見出しごとに分割する。見出しが見つからなければ空文字。"""
    result = {}
    for key, heading in headings:
        m = re.search(rf"###\s*{re.escape(heading)}\s*\n(.*?)(?=\n###\s|\Z)", raw or "", re.S)
        result[key] = (m.group(1).strip() if m else "")
    return result


def _simple_md_to_html(text: str) -> str:
    """簡易Markdown→HTML変換（見出し無し・箇条書きと段落のみ対応。AI生成テキストの整形用）。"""
    out, in_list = [], False
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            if in_list:
                out.append("</ul>")
                in_list = False
            continue
        if line.startswith(("- ", "・", "* ")):
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append(f"<li>{_esc(line[1:].strip())}</li>")
        else:
            if in_list:
                out.append("</ul>")
                in_list = False
            out.append(f"<p>{_esc(line)}</p>")
    if in_list:
        out.append("</ul>")
    return "".join(out) or "<p class=\"muted\">（材料不足のため生成されませんでした）</p>"


def _generate_doc_body_html(con, issue: dict, template_key: str) -> str | None:
    """検討資料の本文HTML（フラグメント）を生成する。材料が無い/AI応答が空ならNone。"""
    headings = _DOC_TEMPLATE_SECTIONS.get(template_key)
    if not headings:
        return None
    source = "\n\n".join(filter(None, [
        _issue_materials_text(con, issue["id"]),
        _issue_notes_text(con, issue["id"]),
    ])).strip()
    if not source:
        return None
    heading_list = "\n".join(f"### {h}" for _, h in headings)
    label = _DOC_TEMPLATE_LABELS.get(template_key, "検討資料")
    prompt = (
        f"あなたは社内向け検討資料の作成者です。以下の検討材料をもとに、"
        f"「{label}」という形式の資料を作成してください。\n\n"
        "必ず次の見出し構成・順序をそのまま使い、各見出しの直後にその内容だけを日本語で書いて"
        "ください（見出しの追加・削除・言い換えは禁止。前置きや結論の繰り返しは不要。"
        "箇条書きを積極的に使い、読みやすく簡潔に。材料に無い/判断できない項目は"
        "「（検討中・材料不足）」とだけ書いてください）。\n\n"
        f"{heading_list}\n\n"
        f"---検討材料ここから---\n論点: {issue.get('issue', '')}\n\n{source}\n---検討材料ここまで---"
    )
    raw = _call_claude_haiku(prompt, timeout=45, max_wait=50, max_tokens=3000)
    if not (raw or "").strip():
        return None
    sections = _parse_doc_sections(raw, headings)
    body = f"<h1>{_esc(issue.get('issue', '') )}</h1><p class=\"muted\">{_esc(label)}</p>"
    for key, heading in headings:
        body += f'<section><h2>{_esc(heading)}</h2>{_simple_md_to_html(sections.get(key, ""))}</section>'
    return body


