_DELIVERY_ACTIVE_CONF_RANK = {"確定": 0, "見込み(クロージング)": 1, "見込み(提案中)": 2}


def _delivery_sort_key(dv: dict, lbl: str) -> tuple:
    """Delivery一覧の並び順（確度×開始週の早い順。確定から始まり、完了系は下に沈める）。
    確度=無効(終了)が最優先で最下位（状態に関わらず）。それ以外は状態で分岐:
    進行中=確度順(確定→見込み(クロージング)→見込み(提案中))が最上位グループ、
    以下、状態=保留→完了→中止の順に下段へ。同グループ内は開始週の早い順（未設定は最後）。"""
    status = dv.get("status") or "進行中"
    if lbl == "無効(終了)":
        bucket = 6
    elif status == "保留":
        bucket = 3
    elif status == "完了":
        bucket = 4
    elif status == "中止":
        bucket = 5
    else:  # 進行中
        bucket = _DELIVERY_ACTIVE_CONF_RANK.get(lbl, 2)
    start = dv.get("start_week") or "9999-99-99"   # 未設定は同グループ内で最後
    return (bucket, start, dv.get("id") or 0)


def _delivery_missing_requirements(con, dv: dict, *, assignments: list | None = None) -> list[str]:
    """#134: Deliveryの必須項目のうち未入力のものをラベルのリストで返す。
    商談がクロージング以降（クロージング/受注）になってから判定する。見込み段階
    （初回アポ実施・要件詰め・提案）では常に空リストを返す＝警告を出さない
    （起票直後から出すと警告だらけになるため。ユーザー確定仕様2026-08-29）。
    どの項目を必須にするかもユーザーに確認して確定：報酬形態・報酬額(月額/総額いずれか)、
    責任者、請求方法・請求期日・請求送付先(請求期日は既定値があるため実質billing_method/
    billing_recipientで判定)、体制(1件以上)、アサイン(owner入り1件以上)、検収額(1件以上)、
    経費請求有無（「不明(要確認)」も有効な回答として扱う。空欄のみ不可）。
    ※支払いサイクル(payment_cycle_months)はDB列にDEFAULT 1があり常に値が入るため、
    「未確認のまま既定値1」と「確認済みで1」を区別できず、必須チェック対象からは除外している。
    成果報酬比率(performance_fee_ratio)は上記とは別枠で、商談の段階に関わらず常にチェックする
    （「成果報酬有無」が有りなのに比率未入力は、段階を問わず単なる入力漏れ＝矛盾データのため。
    2026-08-30）。
    assignmentsを渡すと二重取得を避けられる（一覧画面など既に取得済みの場合）。"""
    dvid = dv.get("id")
    missing = []
    if (dv.get("performance_fee") or "") == "有" and dv.get("performance_fee_ratio") is None:
        missing.append("成果報酬比率")
    if (dv.get("deal_stage") or "") not in ("クロージング", "受注"):
        return missing
    if assignments is None:
        assignments = sfa_db.list_delivery_assignments(con, dvid)
    if dv.get("fee_monthly") is None and dv.get("fee_total") is None:
        missing.append("報酬形態・報酬額")
    if not (dv.get("responsible_owner") or "").strip():
        missing.append("責任者")
    if not (dv.get("billing_method") or "").strip() or not (dv.get("billing_recipient") or "").strip():
        missing.append("請求方法・請求期日・請求送付先")
    if not sfa_db.list_delivery_roles(con, dvid):
        missing.append("体制")
    if not any((a.get("owner") or "").strip() for a in assignments):
        missing.append("アサイン")
    if not sfa_db.list_delivery_receipts(con, dvid):
        missing.append("検収額")
    if not (dv.get("expense_billing") or "").strip():
        missing.append("経費請求有無")
    return missing


def _heat_style(pct: float) -> str:
    """総合負荷率%→背景色（100/150閾値。#75）。"""
    t = sfa_db.DELIVERY_HEAT_THRESHOLDS
    if pct <= 0:
        return "background:transparent;color:#cbd5e1"
    if pct < t["ok"]:
        return "background:#f0fdf4;color:#166534"
    if pct < t["full"]:
        return "background:#dcfce7;color:#166534"
    if pct < t["over"]:
        return "background:#fef3c7;color:#92400e"
    return "background:#dc2626;color:#fff;font-weight:700"


def build_exhibition_funnel_xlsx(con) -> bytes:
    """展示会ファネルを『縦=区分→内訳(理由) × 横=展示会』のマトリクスでxlsx化。Excel転記用。"""
    import openpyxl
    from openpyxl.styles import Font
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    import cowork.weekly_report as weekly_report
    mat = weekly_report.exhibition_funnel_matrix(con, today=_today_jst().isoformat())
    exhs = mat["exhibitions"]
    rows = mat["rows"]
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "展示会ファネル"
    ws.cell(row=1, column=1,
            value=f"展示会ファネル（縦=区分/理由 × 横=展示会）  母集団=lead_pattern='Exh.'  出力日={_today_jst().isoformat()}"
            ).font = Font(bold=True)
    header = ["区分", "内訳（理由）", "合計"] + list(exhs)
    for c, h in enumerate(header, 1):
        ws.cell(row=2, column=c, value=h).font = Font(bold=True)
    r = 3
    for row in rows:
        top = bool(row["kubun"])   # 区分の小計行（合計含む）は太字
        ws.cell(row=r, column=1, value=row["kubun"] or None)
        ws.cell(row=r, column=2, value=row["reason"] or None)
        ws.cell(row=r, column=3, value=row["total"])
        for i, e in enumerate(exhs):
            ws.cell(row=r, column=4 + i, value=row["by_exh"].get(e, 0))
        if top:
            for c in range(1, 4 + len(exhs)):
                ws.cell(row=r, column=c).font = Font(bold=True)
        r += 1
    ws.column_dimensions["A"].width = 28
    ws.column_dimensions["B"].width = 22
    ws.column_dimensions["C"].width = 8
    for i in range(len(exhs)):
        ws.column_dimensions[get_column_letter(4 + i)].width = 18
    ws.freeze_panes = "D3"   # 区分/内訳/合計 の3列＋見出し2行を固定
    bio = BytesIO()
    wb.save(bio)
    return bio.getvalue()


def build_funnel_drill_xlsx(con, all_deals: bool = False) -> bytes:
    """ファネル明細を1行1商談でxlsx化（区分＋重要度/種別L1L2込み）。
    all_deals=False: 展示会由来(lead_pattern='Exh.')／True: 全商談。2列目は展示会名 or 経路。"""
    import openpyxl
    from openpyxl.styles import Font
    from io import BytesIO
    import cowork.weekly_report as weekly_report
    today = _today_jst().isoformat()
    rows = weekly_report.exhibition_deal_rows(con, all_deals=all_deals)
    label = dict(weekly_report.EXH_BUCKETS)
    order = {k: i for i, (k, _) in enumerate(weekly_report.EXH_BUCKETS)}
    for r in rows:
        r["_bucket"] = weekly_report.classify_exhibition_deal(r, today)
    rows.sort(key=lambda r: (order.get(r["_bucket"], 99), -(r.get("mtg") or 0), r.get("id") or 0))
    col2 = "経路" if all_deals else "展示会"
    title = "全案件ファネル明細" if all_deals else "展示会ファネル明細"
    pop = "全商談(open+closed)" if all_deals else "lead_pattern='Exh.'"
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = title[:31]
    # ヘッダーは1行目（タイトル行なし）＝ピボット挿入で表全体を自動認識。母集団/出力日はファイル名に持たせる。
    header = ["区分", col2, "案件名", "アカウント", "重要度", "種別L1", "種別L2",
              "面談回数", "ステージ", "状態", "終了理由", "次回MS", "開発案件",
              "単発(万)", "継続月(万)", "年額換算(万)"]
    for c, h in enumerate(header, 1):
        ws.cell(row=1, column=c, value=h).font = Font(bold=True)
    r = 2
    for row in rows:
        col2v = ((row.get("lead_pattern") or "") or "（未設定）") if all_deals else (row.get("exhibition_name") or "")
        lump = row.get("value_lumpsum") or 0
        rec = row.get("value_recurring") or 0
        vals = [label.get(row["_bucket"], row["_bucket"]), col2v, row.get("deal_name") or "",
                row.get("acc") or "", row.get("importance") or "", row.get("business_type_l1") or "",
                row.get("business_type_l2") or "", row.get("mtg") or 0, row.get("stage") or "",
                ("クローズ" if row.get("status") == "closed" else "open"), row.get("close_reason") or "",
                row.get("next_milestone_date") or "", ("有" if row.get("has_dev") else ""),
                lump, rec, lump + rec * 12]
        for c, v in enumerate(vals, 1):
            ws.cell(row=r, column=c, value=v)
        r += 1
    widths = [26, 16, 26, 20, 8, 14, 14, 9, 14, 8, 14, 12, 8, 10, 11, 12]
    from openpyxl.utils import get_column_letter
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"
    bio = BytesIO()
    wb.save(bio)
    return bio.getvalue()


def build_position_xlsx(con) -> bytes:
    """商談ポジション内訳(KPI-A)の明細を1行1商談でxlsx化（区分＋重要度/種別L1L2込み）。"""
    import openpyxl
    from openpyxl.styles import Font
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    import cowork.weekly_report as weekly_report
    kpi = weekly_report.compute_kpi_pack(con, today=_today_jst())
    A = kpi["A"]
    bl = {"pipe": "パイプライン(進行中)", "won": "受注", "lost": "失注", "cost": "コスト削減(進行中)"}
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "ポジション内訳"
    # ヘッダーは1行目（タイトル行なし）＝ピボット挿入で表全体を自動認識。出力日はファイル名に持たせる。
    header = ["区分", "アカウント", "案件名", "ステージ", "状態", "重要度", "種別L1", "種別L2",
              "単発(万)", "継続月(万)", "年額換算(万)"]
    for c, h in enumerate(header, 1):
        ws.cell(row=1, column=c, value=h).font = Font(bold=True)
    r = 2
    for row in A["rows"]:
        lump = row.get("value_lumpsum") or 0
        rec = row.get("value_recurring") or 0
        vals = [bl.get(row.get("_bucket"), row.get("_bucket")), row.get("account") or "",
                row.get("deal_name") or "", row.get("stage") or "",
                ("クローズ" if row.get("status") == "closed" else "open"),
                row.get("importance") or "", row.get("business_type_l1") or "",
                row.get("business_type_l2") or "", lump, rec, lump + rec * 12]
        for c, v in enumerate(vals, 1):
            ws.cell(row=r, column=c, value=v)
        r += 1
    for i, w in enumerate([22, 20, 26, 14, 8, 8, 14, 14, 10, 11, 12], 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"
    bio = BytesIO()
    wb.save(bio)
    return bio.getvalue()


def build_all_funnel_xlsx(con) -> bytes:
    """全案件ファネルを『1行1商談の縦持ち(tidy)』でxlsx化（Sheet1=明細／Sheet2=経路別CV）。
    区分・経路・重要度・種別L1・種別L2をすべて列として持つため、Excelのピボットで
    任意の切り口（区分×経路、区分×重要度、経路×種別L1 等）に自由に集計できる。"""
    import openpyxl
    from openpyxl.styles import Font
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    import cowork.weekly_report as weekly_report
    today = _today_jst().isoformat()
    rows = weekly_report.exhibition_deal_rows(con, all_deals=True)
    label = dict(weekly_report.EXH_BUCKETS)
    order = {k: i for i, (k, _) in enumerate(weekly_report.EXH_BUCKETS)}
    for r in rows:
        r["_bucket"] = weekly_report.classify_exhibition_deal(r, today)
    rows.sort(key=lambda r: (order.get(r["_bucket"], 99), -(r.get("mtg") or 0), r.get("id") or 0))
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "全案件ファネル明細"
    # ヘッダーは1行目（タイトル行を置かない）＝ピボット挿入時にセル1つ選ぶだけで表全体を自動認識できる。
    # 母集団/出力日はファイル名(all_funnel_YYYY-MM-DD.xlsx)に持たせる。
    # 内訳(理由)＝マトリクスの②④⑩ブレイクダウン相当。tidyでは各行が自分の理由を持つ:
    #   クローズ済→終了理由(close_reason) ／ 未クローズ→「（未クローズ）」。
    # 金額は 単発(万)/継続月(万)/年額換算(万)=単発+継続月×12 を測定値列として末尾に付与。
    header = ["区分", "経路", "重要度", "種別L1", "種別L2", "内訳（理由）",
              "アカウント", "案件名", "面談回数", "ステージ", "状態", "終了理由", "次回MS", "開発案件",
              "単発(万)", "継続月(万)", "年額換算(万)"]
    for c, h in enumerate(header, 1):
        ws.cell(row=1, column=c, value=h).font = Font(bold=True)
    r = 2
    for row in rows:
        route = (row.get("lead_pattern") or "") or "（未設定）"
        closed = row.get("status") == "closed"
        reason = (row.get("close_reason") or "（理由未設定）") if closed else "（未クローズ）"
        lump = row.get("value_lumpsum") or 0
        rec = row.get("value_recurring") or 0
        vals = [label.get(row["_bucket"], row["_bucket"]), route, row.get("importance") or "",
                row.get("business_type_l1") or "", row.get("business_type_l2") or "", reason,
                row.get("acc") or "", row.get("deal_name") or "", row.get("mtg") or 0,
                row.get("stage") or "", ("クローズ" if closed else "open"),
                row.get("close_reason") or "", row.get("next_milestone_date") or "",
                ("有" if row.get("has_dev") else ""), lump, rec, lump + rec * 12]
        for c, v in enumerate(vals, 1):
            ws.cell(row=r, column=c, value=v)
        r += 1
    for i, w in enumerate([26, 12, 8, 14, 14, 16, 20, 26, 9, 14, 8, 14, 12, 8, 10, 11, 12], 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"

    mat = weekly_report.all_funnel_matrix(con, today=today)
    routes = mat["routes"]
    ws2 = wb.create_sheet("経路別CV")
    ws2.cell(row=1, column=1, value=f"経路別CV（到達ベース）  出力日={today}").font = Font(bold=True)
    cvh = ["経路", "母数", "初回面談到達", "2次到達", "受注",
           "CV①初回面談到達率(%)", "CV②初回→2次(%)", "CV③2次→受注(%)"]
    for c, h in enumerate(cvh, 1):
        ws2.cell(row=2, column=c, value=h).font = Font(bold=True)
    cvs = mat["cvs"]
    r = 3
    for key in (["__all__"] + list(routes)):
        c = cvs[key]
        name = "全経路（合計）" if key == "__all__" else key
        for col, v in enumerate([name, c["total"], c["first"], c["second"], c["won"],
                                 c["cv_first"], c["cv_second"], c["cv_won"]], 1):
            cell = ws2.cell(row=r, column=col, value=v)
            if key == "__all__":
                cell.font = Font(bold=True)
        r += 1
    ws2.column_dimensions["A"].width = 16
    for i in range(2, 9):
        ws2.column_dimensions[get_column_letter(i)].width = 18
    bio = BytesIO()
    wb.save(bio)
    return bio.getvalue()


def build_deliveries_xlsx(con) -> bytes:
    """Delivery全テーブル情報のxlsx（一覧＋アサイン明細＋体制）。一覧画面の一括抽出用（#75）。"""
    import openpyxl
    from openpyxl.styles import Font
    from io import BytesIO
    _fee_label = {"monthly": "月額報酬", "total": "総額報酬"}
    wb = openpyxl.Workbook()

    ws = wb.active
    ws.title = "Delivery一覧"
    hdr = ["ID", "アカウント", "商談", "納品案件名", "商談ステージ", "状態", "開始週", "終了週",
           "月数", "事業種別L1", "事業種別L2", "報酬形態", "月額報酬(万)", "総額報酬(万)",
           "総アサイン工数(実想定%/月)",
           "総アサイン工数(請求%/月)", "平均単価(月額・万円/100%)", "アサイン数", "概要", "作成", "更新"]
    for c, h in enumerate(hdr, 1):
        ws.cell(row=1, column=c, value=h).font = Font(bold=True)
    dvs = sfa_db.list_deliveries(con)
    r = 2
    for dv in dvs:
        n_asg = len(sfa_db.list_delivery_assignments(con, dv["id"]))
        months = sfa_db.delivery_month_count(dv.get("start_week"), dv.get("end_week"))
        effort = sfa_db.delivery_total_assign_effort(con, dv["id"])                    # 実想定
        effort_bill = sfa_db.delivery_total_assign_effort(con, dv["id"], use_billing=True)  # 純粋請求
        # 報酬は入力値＋現在の月数で都度再計算（個別ページ・一覧と一致させる）
        _fmon, _ftot = sfa_db.delivery_display_fees(dv)
        # 平均単価(月額) = 月額報酬(円)÷(工数÷100)。工数は請求ベース優先・請求0%は実想定。万円・10万円未満四捨五入
        _eff_price = effort_bill if effort_bill > 0 else effort
        unit_price = (round(_fmon * 10000 * 100 / _eff_price / 100000) * 10
                      if (_fmon and _eff_price > 0) else None)
        _biz_l1, _biz_l2 = sfa_db.delivery_business_type_effective(dv)
        vals = [dv["id"], dv.get("account_name") or "", dv.get("deal_name") or "",
                dv.get("title") or "", dv.get("deal_stage") or "", dv.get("status") or "",
                dv.get("start_week") or "", dv.get("end_week") or "", months,
                _biz_l1 or "", _biz_l2 or "",
                _fee_label.get(dv.get("fee_mode") or "monthly", ""),
                _fmon, _ftot, effort, effort_bill, unit_price, n_asg,
                dv.get("overview") or "", dv.get("created_at") or "", dv.get("updated_at") or ""]
        for c, v in enumerate(vals, 1):
            ws.cell(row=r, column=c, value=v)
        r += 1

    ws2 = wb.create_sheet("アサイン明細")
    hdr2 = ["Delivery ID", "納品案件", "アカウント", "商談", "役割", "区分", "メンバー",
            "開始週", "終了週", "稼働率(実想定)%", "稼働率(請求)%", "メモ"]
    for c, h in enumerate(hdr2, 1):
        ws2.cell(row=1, column=c, value=h).font = Font(bold=True)
    r2 = 2
    for dv in dvs:
        for a in sfa_db.list_delivery_assignments(con, dv["id"]):
            _bill = a.get("fte_billing")
            vals = [dv["id"], dv.get("title") or "", dv.get("account_name") or "", dv.get("deal_name") or "",
                    a.get("role") or "", a.get("member_kind") or "内部", a.get("owner") or "",
                    a.get("from_week") or "", a.get("to_week") or "", a.get("fte_pct"),
                    _bill if _bill is not None else a.get("fte_pct"), a.get("note") or ""]
            for c, v in enumerate(vals, 1):
                ws2.cell(row=r2, column=c, value=v)
            r2 += 1

    ws3 = wb.create_sheet("体制(役割別目標)")
    hdr3 = ["Delivery ID", "納品案件", "役割", "目標(請求)%", "目標(実想定)%"]
    for c, h in enumerate(hdr3, 1):
        ws3.cell(row=1, column=c, value=h).font = Font(bold=True)
    r3 = 2
    for dv in dvs:
        for role in sfa_db.list_delivery_roles(con, dv["id"]):
            vals = [dv["id"], dv.get("title") or "", role.get("role") or "",
                    role.get("fte_billing"), role.get("fte_pct")]
            for c, v in enumerate(vals, 1):
                ws3.cell(row=r3, column=c, value=v)
            r3 += 1

    ws4 = wb.create_sheet("月別入金計画")
    hdr4 = ["Delivery ID", "納品案件", "アカウント", "月", "検収額(万)", "入金額(万)"]
    for c, h in enumerate(hdr4, 1):
        ws4.cell(row=1, column=c, value=h).font = Font(bold=True)
    r4 = 2
    for dv in dvs:
        cf = sfa_db.delivery_cashflow(con, dv["id"])
        for m in cf["months"]:
            vals = [dv["id"], dv.get("title") or "", dv.get("account_name") or "", m,
                    cf["receipts"].get(m), cf["payments"].get(m)]
            for c, v in enumerate(vals, 1):
                ws4.cell(row=r4, column=c, value=v)
            r4 += 1

    buf = BytesIO()
    wb.save(buf)
    return buf.getvalue()


def build_delivery_payment_schedule_xlsx(con) -> bytes:
    """検収/入金の月別金額一覧（1案件×検収/入金の2行のピボット形式）を1枚のxlsxで出力する
    （ユーザー要望2026-08-28: 検収/入金は同じxlsx内に同居させ、「検収/入金」列の値で
    Excelのフィルタ機能により絞り込めるようにする）。一番左は「確度」列（Delivery一覧と
    同じ_delivery_confidenceのラベル）。
    月列は実データの有無に関わらず「今月〜+18ヶ月後」の固定19ヶ月分を表示し、登録が無い月は
    0を入力する。検収額の入力が無い案件も含め全Deliveryを出力する（ユーザー要望2026-08-28続き。
    以前は検収登録が無い案件を除外していたが、予定を立てる前の案件も一覧できるよう変更）。
    責任者/担当者(dv.responsible_owner/handling_owner。個別編集画面でアサインリストから選択)、
    請求方法・請求期日・請求送付先・経費請求有無/メモも列挙する。アサインは全員を1人1列
    （アサインN。全案件を通じた最大人数分の列数に揃え、足りない案件は空欄）でも列挙する。"""
    import openpyxl
    from openpyxl.styles import Font
    from io import BytesIO

    def _na(v):
        """金額列以外の空欄は"na"に統一する（ユーザー要望2026-08-30）。"""
        if v is None or (isinstance(v, str) and not v.strip()):
            return "na"
        return v

    today = _today_jst()
    months = []
    for i in range(19):  # 今月から+18ヶ月後まで(19ヶ月分)
        yy, mm = sfa_db._add_months_ym(today.year, today.month, i)
        months.append(f"{yy:04d}-{mm:02d}")

    # 並び順は確度順(完了含む) × 開始週の早い順（ユーザー要望2026-08-30）。Delivery一覧の
    # `_delivery_sort_key`は状態(完了/中止/保留)を確度より優先して下段に沈めるが、入金予定表は
    # 完了案件も他と同じ確度基準の並びに含めたいため、専用の単純な並び替えキーを使う。
    _XLSX_CONF_RANK = {"確定": 0, "見込み(クロージング)": 1, "見込み(提案中)": 2, "無効(終了)": 3}
    _dvs = []
    for dv in sfa_db.list_deliveries(con):
        _conf_lbl, _ = _delivery_confidence(dv.get("deal_stage") or "", dv.get("deal_status") or "open",
                                            dv.get("confidence_override"))
        _dvs.append((dv, _conf_lbl))
    _dvs.sort(key=lambda t: (_XLSX_CONF_RANK.get(t[1], 4), t[0].get("start_week") or "9999-99-99", t[0]["id"]))

    per_delivery = []  # [(dv, conf_lbl, "検収"|"入金", vals, assignees), ...]
    max_assignees = 0
    for dv, conf_lbl in _dvs:
        cf = sfa_db.delivery_cashflow(con, dv["id"])
        receipts = cf.get("receipts") or {}
        payments = cf.get("payments") or {}
        blocks = sfa_db.list_delivery_assignments(con, dv["id"])
        assignees = sorted({b["owner"] for b in blocks if (b.get("owner") or "").strip()})
        max_assignees = max(max_assignees, len(assignees))
        per_delivery.append((dv, conf_lbl, "検収", receipts, assignees))
        per_delivery.append((dv, conf_lbl, "入金", payments, assignees))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "入金予定表"
    # フォントはメイリオ UI 10pt に統一（ユーザー要望2026-08-30）。
    _font = Font(name="Meiryo UI", size=10)
    _font_bold = Font(name="Meiryo UI", size=10, bold=True)
    fixed_hdr = ["確度", "検収/入金", "#", "クライアント", "案件", "事業種別L1", "事業種別L2", "状態",
                 "開始週", "終了週", "支払いサイト", "責任者", "担当者", "請求方法", "請求期日",
                 "請求送付先", "経費請求有無", "経費請求メモ"]
    hdr = (fixed_hdr + [f"アサイン{i + 1}" for i in range(max_assignees)]
           + [f"{m[2:4]}/{m[5:7]}" for m in months])
    for c, h in enumerate(hdr, 1):
        ws.cell(row=1, column=c, value=h).font = _font_bold
    r = 2
    for dv, conf_lbl, flag, vals, assignees in per_delivery:
        _cycle = dv.get("payment_cycle_months")
        _biz_l1, _biz_l2 = sfa_db.delivery_business_type_effective(dv)
        row = [conf_lbl, flag, dv["id"], _na(dv.get("account_name")), _na(dv.get("title")),
               _na(_biz_l1), _na(_biz_l2),
               _na(dv.get("status")), _na(dv.get("start_week")), _na(dv.get("end_week")),
               _cycle if _cycle is not None else 1,
               _na(dv.get("responsible_owner")), _na(dv.get("handling_owner")),
               _na(dv.get("billing_method")), dv.get("billing_due") or sfa_db.DELIVERY_BILLING_DUE_DEFAULT,
               _na(dv.get("billing_recipient")), _na(dv.get("expense_billing")),
               _na(dv.get("expense_billing_note"))]
        row += [_na(assignees[i] if i < len(assignees) else "") for i in range(max_assignees)]
        row += [(vals.get(m) or 0) for m in months]  # 金額列のみ空欄は0のまま（naにしない）
        for c, v in enumerate(row, 1):
            ws.cell(row=r, column=c, value=v).font = _font
        r += 1
    last_row = r - 1
    last_col = openpyxl.utils.get_column_letter(len(hdr))
    ws.auto_filter.ref = f"A1:{last_col}{max(last_row, 1)}"  # 「検収/入金」列等でExcel側から絞り込み可
    _freeze_col = openpyxl.utils.get_column_letter(len(fixed_hdr) + max_assignees + 1)
    ws.freeze_panes = f"{_freeze_col}2"

    buf = BytesIO()
    wb.save(buf)
    return buf.getvalue()


# 開発要件一覧（#165）のxlsx出力・upload取り込みの両方で使う共通の列定義。
# キーはdev_requirementsのカラム名 or list_dev_requirementsが付与する派生キー、
# 値は列見出し。DEV_REQ_XLSX_DASH_KEYS は「開発有無=無」の行で"-"表示にする対象
# （識別情報・開発有無自体は対象外、sfa_db.DEV_REQUIREMENT_DASH_FIELDS_ON_NO_DEV相当）。
DEV_REQ_XLSX_COLUMNS = [
    ("id", "ID"),
    ("dev_involved", "開発有無"),
    ("link_type_label", "紐づけ種別"),
    ("account_name", "アカウント"),
    ("project_name", "案件名"),
    ("stage", "ステージ"),
    ("owner", "営業主担当"),
    ("start_date", "プロジェクト開始日"),
    ("end_date", "プロジェクト終了日"),
    ("release_target", "リリース希望時期"),
    ("overview", "プロジェクト概要・ゴール"),
    ("scale", "想定利用規模"),
    ("tech_seeds", "必要な技術シード"),
    ("integration_note", "既存システム連携有無"),
    ("confidentiality", "データの機密性"),
    ("budget", "予算感"),
    ("contract_type", "契約形態"),
    ("demo_link", "デモリンク"),
    ("memo", "メモ"),
    ("dev_status", "開発側ステータス"),
    ("created_at", "作成日時"),
    ("updated_at", "更新日時"),
]
DEV_REQ_XLSX_DASH_KEYS = [
    "start_date", "end_date", "release_target", "overview", "scale", "tech_seeds",
    "integration_note", "confidentiality", "budget", "contract_type", "demo_link",
    "memo", "dev_status",
]
# 列幅（Excel列幅単位。ユーザー確認済みの見やすい比率、2026-09-04）。
DEV_REQ_XLSX_COLUMN_WIDTHS = {
    "id": 6, "dev_involved": 10, "link_type_label": 10, "account_name": 18,
    "project_name": 40, "stage": 12, "owner": 10, "start_date": 13, "end_date": 13,
    "release_target": 13, "overview": 45, "scale": 16, "tech_seeds": 16,
    "integration_note": 18, "confidentiality": 12, "budget": 12, "contract_type": 12,
    "demo_link": 20, "memo": 30, "dev_status": 14, "created_at": 16, "updated_at": 16,
}


# 一覧の常時表示11列（#165画面設計フェーズ1、2026-09-04ユーザー確定: 提案9列＋デモリンク＋概要）。
# 残りはxlsxのみ（フェーズ2で行クリック詳細ポップアップに出す予定）。
DEV_REQ_LIST_COLUMNS = [
    ("dev_involved", "開発有無"), ("account_name", "アカウント"), ("project_name", "案件名"),
    ("stage", "ステージ"), ("owner", "営業主担当"), ("start_date", "開始日"),
    ("end_date", "終了日"), ("release_target", "リリース希望"), ("dev_status", "開発側ステータス"),
    ("demo_link", "デモ"), ("overview", "概要"),
]


def dev_requirements_page(con, *, dev_involved: str = "") -> str:
    """開発要件一覧（#165フェーズ1）。Excelライクな一覧表示のみ（インライン編集はフェーズ2）。
    常時表示は11列（DEV_REQ_LIST_COLUMNS）、残りはxlsxダウンロードで見る。"""
    rows = sfa_db.list_dev_requirements(con)
    if dev_involved:
        rows = [r for r in rows if (r.get("dev_involved") or "未判定") == dev_involved]

    def _cell(r, key):
        is_no_dev = (r.get("dev_involved") == "無")
        if is_no_dev and key in DEV_REQ_XLSX_DASH_KEYS:
            return '<span class="muted">-</span>'
        v = r.get(key)
        if key == "demo_link":
            return (f'<a href="{_esc(v)}" target="_blank" rel="noopener" title="{_esc(v)}">🔗</a>'
                    if v else '<span class="muted">-</span>')
        if key == "overview":
            return (f'<span title="{_esc(v)}" style="display:block;overflow:hidden;'
                    f'text-overflow:ellipsis;white-space:nowrap;max-width:320px">{_esc(v)}</span>'
                    if v else '<span class="muted">-</span>')
        if key == "account_name" and r.get("link_type") == "deal":
            return f'<a href="/deal/{r["link_id"]}">{_esc(v or "")}</a>'
        if key == "account_name" and r.get("link_type") == "delivery":
            return f'<a href="/delivery/{r["link_id"]}">{_esc(v or "")}</a>'
        return _esc(v) if v is not None else '<span class="muted">-</span>'

    head = "".join(f'<th>{_esc(label)}</th>' for _, label in DEV_REQ_LIST_COLUMNS)
    body = "".join(
        '<tr>' + "".join(f'<td>{_cell(r, key)}</td>' for key, _ in DEV_REQ_LIST_COLUMNS) + '</tr>'
        for r in rows
    ) or f'<tr><td colspan="{len(DEV_REQ_LIST_COLUMNS)}" class="muted">該当する開発要件がありません。</td></tr>'

    def _tab(label, value):
        active = 'style="font-weight:700"' if dev_involved == value else ''
        href = f"/dev-requirements?dev_involved={_esc(value)}" if value else "/dev-requirements"
        return f'<a href="{href}" {active}>{_esc(label)}</a>'

    tabs = " / ".join(_tab(l, v) for l, v in
                      [("全部", ""), ("有", "有"), ("無", "無"), ("未判定", "未判定")])

    return f"""
    <div class="card">
      <h2 style="margin:0 0 6px">🧩 開発要件一覧</h2>
      <p class="muted" style="font-size:12px;margin:0 0 10px">商談が「提案」以降のステージに到達、
        またはDeliveryが作成されると自動で行が追加されます。開発チームが技術検証・リソース確保を
        判断するためのインプットです。全項目はxlsxで確認・編集できます（アプリ上のインライン編集は今後追加予定）。</p>
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px">
        <div style="font-size:13px">{tabs}</div>
        <a class="btn sec" href="/dev-requirements/export.xlsx" style="font-size:12px">⬇ xlsxダウンロード（全{len(DEV_REQ_XLSX_COLUMNS)}列）</a>
      </div>
      <div style="overflow-x:auto">
        <table style="table-layout:fixed;width:100%">
          <colgroup>
            <col style="width:70px"><col style="width:140px"><col style="width:220px">
            <col style="width:90px"><col style="width:90px"><col style="width:100px">
            <col style="width:100px"><col style="width:110px"><col style="width:110px">
            <col style="width:50px"><col>
          </colgroup>
          <thead><tr>{head}</tr></thead>
          <tbody>{body}</tbody>
        </table>
      </div>
    </div>"""


def build_dev_requirements_xlsx(con) -> bytes:
    """開発要件一覧のxlsx出力（#165）。開発有無=無の行はスケジュール・要件・メモ系を
    "-"表示にする（一覧の可視性を保つ運用）。フォントはメイリオUI 10ptで他のxlsx出力と統一。"""
    import openpyxl
    from openpyxl.styles import Font
    from io import BytesIO

    rows = sfa_db.list_dev_requirements(con)
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "開発要件一覧"
    _font = Font(name="Meiryo UI", size=10)
    _font_bold = Font(name="Meiryo UI", size=10, bold=True)

    hdr = [label for _, label in DEV_REQ_XLSX_COLUMNS]
    for c, h in enumerate(hdr, 1):
        ws.cell(row=1, column=c, value=h).font = _font_bold
    for c, (key, _label) in enumerate(DEV_REQ_XLSX_COLUMNS, 1):
        w = DEV_REQ_XLSX_COLUMN_WIDTHS.get(key)
        if w:
            ws.column_dimensions[openpyxl.utils.get_column_letter(c)].width = w

    for r, row in enumerate(rows, 2):
        row = dict(row)
        row["link_type_label"] = "商談" if row.get("link_type") == "deal" else "Delivery"
        is_no_dev = (row.get("dev_involved") == "無")
        for c, (key, _label) in enumerate(DEV_REQ_XLSX_COLUMNS, 1):
            if is_no_dev and key in DEV_REQ_XLSX_DASH_KEYS:
                v = "-"
            else:
                v = row.get(key)
            ws.cell(row=r, column=c, value=v).font = _font

    last_col = openpyxl.utils.get_column_letter(len(hdr))
    ws.auto_filter.ref = f"A1:{last_col}{max(len(rows) + 1, 1)}"
    ws.freeze_panes = "A2"

    buf = BytesIO()
    wb.save(buf)
    return buf.getvalue()


# ── 業務フロー作成機能（#164、フェーズ1: DBスキーマ＋一覧＋静的グリッド表示） ──────
def _business_flow_suggest_category(name: str, description: str) -> str:
    """新規フロー作成時、名前・説明からHaikuで分類（例:「経理業務」）を1つだけ提案する。
    人間が詳細画面でいつでも修正できるため、提案を鵜呑みにする設計で問題ない。
    APIキー未設定・失敗時は空文字（未分類のまま作成）。"""
    prompt = (
        "次の社内業務フローの名前・説明から、分類名を1つだけ日本語の短い名詞句（例: 経理業務、"
        "契約業務、人事業務）で出力してください。説明文や記号は不要、分類名のみを出力してください。\n\n"
        f"フロー名: {name}\n説明: {description or '(なし)'}"
    )
    out = _call_claude_haiku(prompt, timeout=15, max_wait=18, max_tokens=30)
    return out.strip().splitlines()[0].strip() if out.strip() else ""


def _business_flow_ai_questions(name: str, description: str) -> list[str]:
    """フロー名・説明からHaiku(Web検索併用)で、ドラフト作成に必要な質問を3〜5件生成する
    （#164追加要望2026-09-04: 「白紙から作るのは大変なので、AIと質疑してドラフトを作りたい」）。
    ANTHROPIC_API_KEY未設定・anthropicライブラリ未インストール・生成失敗時は空リスト
    （呼び出し側は「生成に失敗しました」と案内し、手動追加に誘導する）。"""
    if not ANTHROPIC_API_KEY:
        return []
    try:
        import anthropic  # noqa: PLC0415
    except ImportError:
        return []
    try:
        client = anthropic.Anthropic()
        prompt = (
            "社内の業務フロー図（部署/担当者レーン×工程プロセスのスイムレーン図）を作成する準備をしています。\n"
            f"フロー名: {name}\n説明: {description or '(未入力)'}\n\n"
            "このフローの実態を把握するために、担当者に聞くべき質問を3〜5個、日本語で考えてください。"
            "必要であれば同種の業務の一般的な進め方をWeb検索で調べて参考にしてください。"
            "質問は「どの部署/担当者が関わるか」「工程の順序」「承認/分岐/例外処理の有無」など、"
            "後でスイムレーン図（レーン×プロセス×タスクボックス）を組み立てるのに必要な情報に絞ってください。\n\n"
            '回答はJSON配列のみで返してください（説明不要）。例: ["質問1", "質問2", "質問3"]'
        )
        response = client.messages.create(
            model="claude-haiku-4-5",
            max_tokens=1024,
            tools=[{"type": "web_search_20250305", "name": "web_search"}],
            messages=[{"role": "user", "content": prompt}],
        )
        for block in response.content:
            if getattr(block, "text", None):
                text = block.text.strip()
                start, end = text.find("["), text.rfind("]") + 1
                if start >= 0 and end > start:
                    qs = json.loads(text[start:end])
                    return [str(q).strip() for q in qs if str(q).strip()][:5]
    except Exception as _e:  # noqa: BLE001
        print(f"[business-flow-ai] 質問生成失敗: {_e}", flush=True)
    return []


def _business_flow_ai_draft(name: str, description: str, qa_pairs: list[tuple[str, str]]) -> dict:
    """質疑応答を踏まえ、レーン・プロセス・ボックスのドラフト構成をJSONで生成する。
    失敗時は空dict（呼び出し側は何も作成しない・エラー表示のみ）。"""
    if not ANTHROPIC_API_KEY:
        return {}
    try:
        import anthropic  # noqa: PLC0415
    except ImportError:
        return {}
    qa_text = "\n".join(f"Q: {q}\nA: {a}" for q, a in qa_pairs if (a or "").strip())
    try:
        client = anthropic.Anthropic()
        prompt = (
            "社内の業務フロー図（部署/担当者レーン×工程プロセスのスイムレーン図）のドラフトを作成してください。\n"
            f"フロー名: {name}\n説明: {description or '(未入力)'}\n\n質疑応答:\n{qa_text or '(なし)'}\n\n"
            "レーン（3〜5本程度、部署/担当者名）、プロセス（工程、3〜6個程度、実施順）、"
            "各レーン×プロセスに配置するタスクボックス（無理に全セルを埋めなくてよい。実際に発生する"
            "作業のみ）を考えてください。必要であれば同種の業務の一般的な進め方をWeb検索で参考にしてください。\n\n"
            "回答は次のJSON形式のみで返してください（説明・コメント不要）:\n"
            '{"lanes": ["部署A", "部署B"], "processes": ["工程1", "工程2"], '
            '"boxes": [{"lane": "部署A", "process": "工程1", "label": "タスク名"}]}\n'
            "lane/processの値は必ず上のlanes/processesリストに含まれる文字列と完全一致させてください。"
        )
        response = client.messages.create(
            model="claude-haiku-4-5",
            max_tokens=2000,
            tools=[{"type": "web_search_20250305", "name": "web_search"}],
            messages=[{"role": "user", "content": prompt}],
        )
        for block in response.content:
            if getattr(block, "text", None):
                text = block.text.strip()
                start, end = text.find("{"), text.rfind("}") + 1
                if start >= 0 and end > start:
                    data = json.loads(text[start:end])
                    if isinstance(data, dict) and isinstance(data.get("lanes"), list):
                        return data
    except Exception as _e:  # noqa: BLE001
        print(f"[business-flow-ai] ドラフト生成失敗: {_e}", flush=True)
    return {}


def business_flows_page(con) -> str:
    """業務フロー一覧（#164）。表形式1本（分類はグルーピングせず列として表示、
    2026-09-04ユーザー確定: 「フロー一覧は表形式で。分類ごとにセクションを分けない」）。"""
    flows = sfa_db.list_business_flows(con)
    flows_sorted = sorted(flows, key=lambda fl: (fl.get("category") or "未分類", fl.get("name") or ""))

    def _flow_row(fl):
        return (
            f'<tr><td>{_esc(fl.get("category") or "未分類")}</td>'
            f'<td><a href="/business-flow/{fl["id"]}">{_esc(fl["name"])}</a></td>'
            f'<td class="muted">{_esc(fl.get("description") or "")}</td>'
            f'<td>{fl["lane_count"]}</td><td>{fl["process_count"]}</td>'
            f'<td class="muted" style="font-size:12px">{_esc((fl.get("updated_at") or "")[:16])}</td>'
            f'<td style="white-space:nowrap">'
            f'<form method="post" action="/business-flow/{fl["id"]}/duplicate" style="display:inline">'
            f'<button type="submit" class="btn sec" style="font-size:12px">複製</button></form> '
            f'<form method="post" action="/business-flow/{fl["id"]}/delete" style="display:inline" '
            f'onsubmit="return confirm(\'このフロー図を削除します。よろしいですか？\')">'
            f'<button type="submit" class="btn sec" style="color:#c53030;font-size:12px">削除</button></form></td></tr>'
        )

    table = (
        '<table><tr><th>分類</th><th>フロー名</th><th>説明</th><th>レーン数</th>'
        '<th>プロセス数</th><th>更新</th><th></th></tr>'
        + "".join(_flow_row(fl) for fl in flows_sorted)
        + '</table>'
    ) if flows else '<p class="muted">まだ業務フロー図がありません。</p>'

    return f"""
    <div class="card">
      <h2 style="margin:0 0 8px">🔀 業務フロー一覧</h2>
      <p class="muted" style="font-size:12px;margin:0 0 12px">部署/担当者レーン×プロセスのスイムレーン図で、
        請求書処理等の社内業務フローを管理します。既存フローの「複製」から作り始めることもできます。</p>
      <form method="post" action="/business-flows/new"
            style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;background:#f8fafc;border-radius:8px;padding:10px">
        <label style="font-size:12px">フロー名＊<br><input type="text" name="name" required
               placeholder="請求書処理フロー" style="width:220px"></label>
        <label style="font-size:12px;flex:1;min-width:200px">説明<br>
               <input type="text" name="description" placeholder="任意" style="width:100%"></label>
        <button class="btn" type="submit" style="font-size:12px">＋ 新規フロー作成</button>
      </form>
      <p class="muted" style="font-size:11px;margin:6px 0 0">分類はHaikuが名前・説明から自動提案します
        （作成後、詳細画面でいつでも修正できます）。</p>
    </div>
    <div class="card">{table}</div>"""


def business_flow_detail_page(con, flow_id: int, *, ai_questions: list[str] | None = None,
                              ai_error: str = "") -> str:
    """業務フロー編集画面（フェーズ1: 手動追加のみ・静的グリッド表示。ドラッグ移動・矢印はフェーズ2/3）。
    ai_questions: AIが生成した質問（Q&Aフォームを表示中）。ai_error: 質問/ドラフト生成失敗時のメッセージ。"""
    flow = sfa_db.get_business_flow(con, flow_id)
    if not flow:
        return '<div class="card">業務フロー図が見つかりません。<a href="/business-flows">← 一覧へ</a></div>'
    lanes = sfa_db.list_business_flow_lanes(con, flow_id)
    processes = sfa_db.list_business_flow_processes(con, flow_id)
    boxes = sfa_db.list_business_flow_boxes(con, flow_id)
    box_by_cell: dict = {}
    for b in boxes:
        box_by_cell.setdefault((b["lane_id"], b["process_id"]), []).append(b)

    def _box_html(b):
        return (
            f'<div style="background:#fff;border:1px solid #d8dee8;border-radius:6px;'
            f'padding:5px 7px;margin-bottom:4px;font-size:12px;display:flex;'
            f'align-items:center;justify-content:space-between;gap:6px">'
            f'<span>{_esc(b["label"])}</span>'
            f'<form method="post" action="/business-flow-box/{b["id"]}/delete" style="margin:0" '
            f'onsubmit="return confirm(\'このボックスを削除しますか？\')">'
            f'<button type="submit" class="btn sec" style="font-size:10px;padding:1px 5px">×</button></form></div>'
        )

    def _add_box_form(lane_id, process_id):
        return (
            f'<form method="post" action="/business-flow/{flow_id}/box" style="display:flex;gap:3px">'
            f'<input type="hidden" name="lane_id" value="{lane_id}">'
            f'<input type="hidden" name="process_id" value="{process_id}">'
            f'<input type="text" name="label" placeholder="＋タスク" required '
            f'style="font-size:11px;padding:2px 4px;width:100%">'
            f'<button type="submit" class="btn sec" style="font-size:11px;padding:1px 6px">追加</button></form>'
        )

    # ドラッグで並び替え可能にするため、レーン<th>・プロセス<th>ともdata属性+⠿ハンドルを付ける
    # （#164追加要望2026-09-04:「プロセス、レーンをドラッグを動かせるように」）。
    # あわせて見た目のコントラストを強化（同要望:「現在は薄く読みづらい」への対応）。
    _LANE_HDR_BG = "#eef2ff"; _PROC_HDR_BG = "#f1f5f9"; _HDR_BORDER = "1px solid #94a3b8"
    _CELL_BORDER = "1px solid #cbd5e1"
    head_cells = "".join(
        f'<th data-process-id="{p["id"]}" style="min-width:160px;background:{_PROC_HDR_BG};'
        f'border:{_HDR_BORDER};padding:8px">'
        f'<div style="display:flex;align-items:center;justify-content:space-between;gap:4px">'
        f'<span class="drag-handle" draggable="true" title="ドラッグで並び替え" '
        f'style="cursor:grab;color:#64748b;font-size:14px">⠿</span>'
        f'<span style="font-weight:700;color:#1e293b;font-size:13px">{_esc(p["name"])}</span>'
        f'<form method="post" action="/business-flow-process/{p["id"]}/delete" style="margin:0" '
        f'onsubmit="return confirm(\'このプロセス列を削除します（列内のボックスも削除されます）。よろしいですか？\')">'
        f'<button type="submit" class="btn sec" style="font-size:10px;padding:1px 5px">×</button></form></div></th>'
        for p in processes
    )
    body_rows = ""
    for lane in lanes:
        cells = "".join(
            f'<td data-process-id="{p["id"]}" style="vertical-align:top;background:#fff;'
            f'border:{_CELL_BORDER};padding:8px">'
            f'{"".join(_box_html(b) for b in box_by_cell.get((lane["id"], p["id"]), []))}'
            f'{_add_box_form(lane["id"], p["id"])}</td>'
            for p in processes
        )
        body_rows += (
            f'<tr data-lane-id="{lane["id"]}">'
            f'<th style="text-align:left;vertical-align:top;white-space:nowrap;background:{_LANE_HDR_BG};'
            f'border:{_HDR_BORDER};padding:8px">'
            f'<div style="display:flex;align-items:center;gap:6px">'
            f'<span class="drag-handle" draggable="true" title="ドラッグで並び替え" '
            f'style="cursor:grab;color:#64748b;font-size:14px">⠿</span>'
            f'<span style="font-weight:700;color:#1e293b;font-size:13px;flex:1">{_esc(lane["name"])}</span>'
            f'<form method="post" action="/business-flow-lane/{lane["id"]}/delete" style="margin:0" '
            f'onsubmit="return confirm(\'このレーンを削除します（レーン内のボックスも削除されます）。よろしいですか？\')">'
            f'<button type="submit" class="btn sec" style="font-size:10px;padding:1px 5px">×</button></form></div>'
            f'</th>{cells}</tr>'
        )

    # AIドラフト機能（#164追加要望2026-09-04）。白紙のフロー（レーン・プロセスとも0件）にのみ出す
    # （ドラフト後は既存の手動編集フォームで人間が修正・確定する運用のため、追加済みなら不要）。
    ai_draft_block = ""
    if not lanes and not processes:
        if ai_error:
            ai_draft_block = (f'<div class="card"><p style="color:#b91c1c;font-size:13px;margin:0">'
                              f'⚠️ {_esc(ai_error)}</p></div>')
        elif ai_questions:
            qa_rows = "".join(
                f'<div style="margin-bottom:10px">'
                f'<label style="font-size:12px;font-weight:600;display:block;margin-bottom:3px">{_esc(q)}</label>'
                f'<input type="hidden" name="question" value="{_esc(q)}">'
                f'<textarea name="answer" rows="2" style="width:100%;font-size:13px" '
                f'placeholder="わかる範囲で回答してください（空欄可）"></textarea></div>'
                for q in ai_questions
            )
            ai_draft_block = f"""
            <div class="card">
              <h3 style="margin:0 0 8px">🤖 AIからの質問</h3>
              <p class="muted" style="font-size:12px;margin:0 0 10px">回答を踏まえてドラフト（レーン・プロセス・
                タスクボックス）を作成します。わからない項目は空欄のままでも構いません。</p>
              <form method="post" action="/business-flow/{flow_id}/ai-draft/build">
                {qa_rows}
                <button type="submit" class="btn" style="font-size:12px">ドラフトを作成</button>
              </form>
            </div>"""
        else:
            ai_draft_block = f"""
            <div class="card">
              <h3 style="margin:0 0 6px">🤖 AIにドラフトを作ってもらう</h3>
              <p class="muted" style="font-size:12px;margin:0 0 10px">フロー名・説明をもとにAIがWeb検索も使って
                質問を考えます。回答するとレーン・プロセス・タスクボックスのドラフトを自動生成します
                （生成後は下のフォームで自由に修正・確定できます）。</p>
              <form method="post" action="/business-flow/{flow_id}/ai-draft/questions">
                <button type="submit" class="btn sec" style="font-size:12px">質問を生成</button>
              </form>
            </div>"""

    grid = "まだレーン・プロセスがありません。下のフォームから追加してください。"
    if lanes or processes:
        # レーンのみ/プロセスのみの状態でも、追加済みのものが見える・削除できるように
        # 常に表(ヘッダー行+レーン行)を描く（片方が0件でもヘッダーだけ/行だけの表になる）。
        grid = (f'<div style="overflow-x:auto"><table id="bfGridTable" style="border-collapse:collapse">'
                f'<tr><th style="border:{_HDR_BORDER};background:{_PROC_HDR_BG}"></th>{head_cells}</tr>'
                f'{body_rows}</table></div>')
        if not processes:
            grid += '<p class="muted" style="font-size:12px;margin-top:8px">プロセス（工程）を追加すると、ボックスを配置できるようになります。</p>'
        elif not lanes:
            grid += '<p class="muted" style="font-size:12px;margin-top:8px">レーン（部署/担当者）を追加すると、ボックスを配置できるようになります。</p>'

    return f"""
    <div class="card">
      <p style="margin:0 0 10px"><a href="/business-flows">← 業務フロー一覧へ</a></p>
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap">
        <h2 style="margin:0">{_esc(flow["name"])}</h2>
        <form method="post" action="/business-flow/{flow_id}/delete"
              onsubmit="return confirm(\'このフロー図全体を削除します。よろしいですか？\')">
          <button type="submit" class="btn sec" style="color:#c53030;font-size:12px">フロー図を削除</button>
        </form>
      </div>
      <form method="post" action="/business-flow/{flow_id}/update"
            style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-top:10px">
        <label style="font-size:12px">フロー名＊<br><input type="text" name="name" required
               value="{_esc(flow["name"])}" style="width:220px"></label>
        <label style="font-size:12px;flex:1;min-width:200px">説明<br>
               <input type="text" name="description" value="{_esc(flow.get("description") or "")}"
                      style="width:100%"></label>
        <label style="font-size:12px">分類<br><input type="text" name="category"
               value="{_esc(flow.get("category") or "")}" placeholder="経理業務" style="width:150px"></label>
        <button type="submit" class="btn sec" style="font-size:12px">保存</button>
      </form>
    </div>
    {ai_draft_block}
    <div class="card">
      <h3 style="margin:0 0 10px">フロー図（⠿をドラッグしてレーン・プロセスの並び替えができます。
        ボックスのドラッグ移動・矢印接続は今後追加予定）</h3>
      {grid}
      <div style="display:flex;gap:20px;flex-wrap:wrap;margin-top:14px;padding-top:14px;border-top:1px solid #e6e9f0">
        <form method="post" action="/business-flow/{flow_id}/lane" style="display:flex;gap:6px;align-items:flex-end">
          <label style="font-size:12px">＋レーン追加（部署/担当者）<br>
                 <input type="text" name="name" required placeholder="経理/磯部" style="width:180px"></label>
          <button type="submit" class="btn sec" style="font-size:12px">追加</button>
        </form>
        <form method="post" action="/business-flow/{flow_id}/process" style="display:flex;gap:6px;align-items:flex-end">
          <label style="font-size:12px">＋プロセス追加（工程）<br>
                 <input type="text" name="name" required placeholder="請求書受領" style="width:180px"></label>
          <button type="submit" class="btn sec" style="font-size:12px">追加</button>
        </form>
      </div>
    </div>
    <script>
    function initBusinessFlowDrag(flowId) {{
      var table = document.getElementById('bfGridTable'); if (!table) return;
      var headerRow = table.rows[0];
      // レーン(行)のドラッグ並び替え
      Array.from(table.rows).slice(1).forEach(function(tr) {{
        var handle = tr.querySelector('th .drag-handle'); if (!handle) return;
        handle.addEventListener('dragstart', function(e) {{
          e.dataTransfer.effectAllowed = 'move'; table._draggingRow = tr;
        }});
        tr.addEventListener('dragover', function(e) {{
          e.preventDefault();
          var dragging = table._draggingRow; if (!dragging || dragging === tr) return;
          var rect = tr.getBoundingClientRect();
          if (e.clientY < rect.top + rect.height / 2) tr.parentNode.insertBefore(dragging, tr);
          else tr.parentNode.insertBefore(dragging, tr.nextSibling);
        }});
        handle.addEventListener('dragend', function() {{
          table._draggingRow = null;
          var ids = Array.from(table.rows).slice(1).map(function(r) {{ return r.dataset.laneId; }});
          fetch('/business-flow/' + flowId + '/lanes/reorder', {{method: 'POST',
            headers: {{'Content-Type': 'application/x-www-form-urlencoded'}}, body: 'order=' + ids.join(',')}});
        }});
      }});
      // プロセス(列)のドラッグ並び替え。ヘッダーの並びを直接動かし、確定時に各行のセルもその順に揃える。
      Array.from(headerRow.cells).slice(1).forEach(function(th) {{
        var handle = th.querySelector('.drag-handle'); if (!handle) return;
        handle.addEventListener('dragstart', function(e) {{
          e.dataTransfer.effectAllowed = 'move'; table._draggingCol = th;
        }});
        th.addEventListener('dragover', function(e) {{
          e.preventDefault();
          var dragging = table._draggingCol; if (!dragging || dragging === th) return;
          var rect = th.getBoundingClientRect();
          if (e.clientX < rect.left + rect.width / 2) th.parentNode.insertBefore(dragging, th);
          else th.parentNode.insertBefore(dragging, th.nextSibling);
        }});
        handle.addEventListener('dragend', function() {{
          table._draggingCol = null;
          var order = Array.from(headerRow.cells).slice(1).map(function(c) {{ return c.dataset.processId; }});
          Array.from(table.rows).slice(1).forEach(function(tr) {{
            var cellMap = {{}};
            Array.from(tr.cells).slice(1).forEach(function(td) {{ cellMap[td.dataset.processId] = td; }});
            order.forEach(function(pid) {{ if (cellMap[pid]) tr.appendChild(cellMap[pid]); }});
          }});
          fetch('/business-flow/' + flowId + '/processes/reorder', {{method: 'POST',
            headers: {{'Content-Type': 'application/x-www-form-urlencoded'}}, body: 'order=' + order.join(',')}});
        }});
      }});
    }}
    initBusinessFlowDrag({flow_id});
    </script>"""


def build_deals_full_xlsx(con) -> bytes:
    """商談・アカウント・活動履歴を全カラムJOINしたxlsx（1商談1活動=1行、活動がない商談も1行残す）。
    カラムはPRAGMA table_infoで動的取得するため、スキーマ変更が入っても手直し不要。"""
    import openpyxl
    from openpyxl.styles import Font
    from io import BytesIO

    deal_cols = [r[1] for r in con.execute("PRAGMA table_info(deals)")]
    account_cols = [r[1] for r in con.execute("PRAGMA table_info(accounts)")]
    activity_cols = [r[1] for r in con.execute("PRAGMA table_info(activities)")]

    select_parts = (
        [f"d.{c} AS 商談_{c}" for c in deal_cols]
        + [f"a.{c} AS アカウント_{c}" for c in account_cols]
        + [f"act.{c} AS 活動履歴_{c}" for c in activity_cols]
    )
    query = (
        "SELECT " + ", ".join(select_parts) + " "
        "FROM deals d "
        "LEFT JOIN accounts a ON a.id = d.account_id "
        "LEFT JOIN activities act ON act.deal_id = d.id "
        "ORDER BY d.id, act.occurred_on, act.id"
    )
    rows = con.execute(query).fetchall()
    headers = [f"商談.{c}" for c in deal_cols] + [f"アカウント.{c}" for c in account_cols] + [f"活動履歴.{c}" for c in activity_cols]

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "商談_活動履歴_全件"
    for c, h in enumerate(headers, 1):
        ws.cell(row=1, column=c, value=h).font = Font(bold=True)
    for r, row in enumerate(rows, 2):
        for c, v in enumerate(row, 1):
            ws.cell(row=r, column=c, value=v)
    ws.freeze_panes = "A2"

    buf = BytesIO()
    wb.save(buf)
    return buf.getvalue()


def deliveries_page(con) -> str:
    """Delivery案件一覧（検索/フィルタ・インライン編集・一括削除・平均FTE）。#75。"""
    _statuses = sfa_db.DELIVERY_STATUSES
    _dvs_with_lbl = []
    for dv in sfa_db.list_deliveries(con):
        lbl, col = _delivery_confidence(dv.get("deal_stage") or "", dv.get("deal_status") or "open", dv.get("confidence_override"))
        _dvs_with_lbl.append((dv, lbl, col))
    _dvs_with_lbl.sort(key=lambda t: _delivery_sort_key(t[0], t[1]))
    rows = ""
    for dv, lbl, col in _dvs_with_lbl:
        _id = dv["id"]
        blocks = sfa_db.list_delivery_assignments(con, _id)
        who = "、".join(sorted({b["owner"] for b in blocks})) or "—"
        # 総アサイン工数と同じロジック（期間平均の合計稼働率）: 実想定＋純粋請求（請求0%は「-」）。
        _eff_a = sfa_db.delivery_total_assign_effort(con, _id)                    # 実想定
        _eff_b = sfa_db.delivery_total_assign_effort(con, _id, use_billing=True)  # 純粋請求
        if blocks:
            _bill_disp = f'{_num_pct(_eff_b)}%' if _eff_b > 0 else '-%'
            avg_html = f'実{_num_pct(_eff_a)}% <span class="muted" style="font-size:10px">/ 請{_bill_disp}</span>'
        else:
            avg_html = '<span class="muted">—</span>'
        _st_opts = "".join(
            f'<option value="{_esc(s)}"{" selected" if (dv.get("status") or "進行中") == s else ""}>{_esc(s)}</option>'
            for s in _statuses)
        # 報酬（総額/月額）と平均単価(月額)。工数は請求ベース優先・請求0%(成果物ベース)は実想定で試算。
        # 報酬は入力値＋現在の月数で都度再計算（個別ページのライブ換算と一致させる）。
        _fmon, _ftot = sfa_db.delivery_display_fees(dv)
        _eff = _eff_b if _eff_b > 0 else _eff_a
        _tot_html = f'{_ftot:,.0f}' if _ftot is not None else '<span class="muted">—</span>'
        _mon_html = f'{_fmon:,.0f}' if _fmon is not None else '<span class="muted">—</span>'
        _up_html = (f'{round(_fmon * 10000 * 100 / _eff / 100000) * 10:,}'
                    if (_fmon and _eff > 0) else '<span class="muted">—</span>')
        _search = _esc(((dv.get("account_name") or "") + " " + (dv.get("title") or "")).lower())
        _missing = _delivery_missing_requirements(con, dv, assignments=blocks)
        _warn_badge = (
            f'<span title="未入力の必須項目: {_esc("、".join(_missing))}" '
            'style="margin-left:4px;cursor:help">⚠️</span>') if _missing else ""
        _biz_l1, _biz_l2 = sfa_db.delivery_business_type_effective(dv)
        rows += f"""
        <tr class="dv-row" data-search="{_search}" data-status="{_esc(dv.get('status') or '進行中')}" data-conf="{lbl}"
            data-bizl1="{_esc(_biz_l1 or '')}" data-bizl2="{_esc(_biz_l2 or '')}">
          <td style="width:26px"><input type="checkbox" name="ids" value="{_id}"></td>
          <td class="muted" style="font-size:.8em"><a href="/delivery/{_id}">#{_id}</a></td>
          <td>{_esc(dv.get('account_name') or '—')}</td>
          <td><input type="text" value="{_esc(dv.get('title') or '')}" style="width:220px;font-size:12px"
                 onchange="dvField({_id},'title',this.value)"></td>
          <td style="white-space:nowrap"><span style="background:{col};color:#fff;border-radius:5px;padding:1px 7px;font-size:11px;white-space:nowrap;display:inline-block">{lbl}</span>{_warn_badge}</td>
          <td><select style="font-size:12px;min-width:104px" onchange="dvField({_id},'status',this.value)">{_st_opts}</select></td>
          <td><input type="date" value="{_esc(dv.get('start_week') or '')}" style="font-size:11px"
                 onchange="dvField({_id},'start_week',this.value)"></td>
          <td><input type="date" value="{_esc(dv.get('end_week') or '')}" style="font-size:11px"
                 onchange="dvField({_id},'end_week',this.value)"></td>
          <td style="text-align:right;white-space:nowrap">{_tot_html}</td>
          <td style="text-align:right;white-space:nowrap">{_mon_html}</td>
          <td style="text-align:right;white-space:nowrap">{_up_html}</td>
          <td style="white-space:nowrap">{avg_html}</td>
          <td>{_esc(who)}</td>
          <td><a class="btn sec" style="font-size:11px" href="/delivery/{_id}">編集</a></td>
        </tr>"""
    if not rows:
        rows = '<tr><td colspan=14 class=muted>Deliveryはまだありません。商談が「提案」に至ると自動で起票されます。</td></tr>'
    _cands = [d for d in sfa_db.list_deals(con, status="open")
              if (d.get("stage") or "") in sfa_db.DELIVERY_TRIGGER_STAGES]
    _cand_opts = "".join(
        f'<option value="{d["id"]}">{_esc(d.get("account_name") or "")}：{_esc(d.get("deal_name") or "")}（{_esc(d.get("stage") or "")}）</option>'
        for d in _cands)
    _st_filter = "".join(f'<option value="{_esc(s)}">{_esc(s)}</option>' for s in _statuses)
    # 事業種別L1/L2フィルタ（ユーザー要望2026-08-30）。値は現在の有効事業種別(delivery_business_type_effective)。
    _biz_l1_filter = "".join(
        f'<option value="{_esc(l1)}">{_esc(l1)}</option>' for l1 in sfa_db.get_master_list(con, "business_type_l1"))
    _biz_l2_seen: list = []
    for _l2s in sfa_db.get_business_type_tree(con).values():
        for _l2 in _l2s:
            if _l2 not in _biz_l2_seen:
                _biz_l2_seen.append(_l2)
    _biz_l2_filter = "".join(f'<option value="{_esc(l2)}">{_esc(l2)}</option>' for l2 in _biz_l2_seen)
    # 誤起票の掃除: アサイン未入力（空）のDelivery件数
    _empty_n = con.execute(
        "SELECT COUNT(*) c FROM deliveries WHERE id NOT IN "
        "(SELECT DISTINCT delivery_id FROM delivery_assignments)").fetchone()["c"]
    _empty_cleanup = (
        f'<form method="post" action="/deliveries/delete_empty" style="margin-top:6px" '
        f'onsubmit="return confirm(\'アサイン未入力のDelivery {_empty_n}件を削除します。よろしいですか？\')">'
        f'<button class="btn sec" style="font-size:12px;color:#c53030">🧹 アサイン未入力のDeliveryを一括削除（{_empty_n}件）</button>'
        f'</form>') if _empty_n else ""
    return f"""
    <div class="card">
      <h2 style="margin:0 0 4px">🚚 Delivery（受注後・アサイン計画）</h2>
      <p class="muted" style="margin:0 0 10px">商談が「提案」に至ると自動でDelivery案件が起票されます。案件名・状態・期間はこの一覧で直接編集できます（期間は初期入力のガイド用。既存アサインの週は変わりません）。
        <a href="/base-workload">▶ ベース工数を設定</a></p>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px">
        <input type="text" id="dvSearch" placeholder="🔍 案件名・クライアントで検索" style="font-size:12px;padding:4px 8px;width:260px" oninput="_deb('filterDeliveries')">
        <select id="dvStatusF" style="font-size:12px" onchange="filterDeliveries()"><option value="">全状態</option>{_st_filter}</select>
        <select id="dvConfF" style="font-size:12px" onchange="filterDeliveries()"><option value="">全確度</option>
          {"".join(f'<option value="{_esc(c)}">{_esc(c)}</option>' for c in sfa_db.DELIVERY_CONFIDENCE_LEVELS)}</select>
        <select id="dvBizL1F" style="font-size:12px" onchange="filterDeliveries()"><option value="">全事業種別L1</option>{_biz_l1_filter}</select>
        <select id="dvBizL2F" style="font-size:12px" onchange="filterDeliveries()"><option value="">全事業種別L2</option>{_biz_l2_filter}</select>
        <span id="dvCount" class="muted" style="font-size:12px"></span>
        <span style="margin-left:auto;display:inline-flex;gap:6px;flex-wrap:wrap">
          <a class="btn sec" href="/deliveries/payment-schedule.xlsx" style="font-size:12px"
             title="案件×月の一覧表。先頭列「検収/入金」でExcel側から絞り込み可">📥 入金予定表</a>
          <a class="btn sec" href="/deliveries/export.xlsx" style="font-size:12px">📥 xlsx出力（全件・全テーブル）</a>
        </span>
      </div>
      <form id="dv_bulk" method="post" action="/deliveries/bulk_delete"
            onsubmit="return confirm('選択したDeliveryを削除します。アサインも消えます。よろしいですか？')">
      <div style="overflow:auto;max-height:72vh"><table style="min-width:1380px;width:100%">
        <tr>
          <th class="sticky" style="width:26px"><input type="checkbox" id="dvAll" onclick="dvToggleAll(this)" title="表示中を全選択"></th>
          <th class="sticky">#</th><th class="sticky">クライアント</th><th class="sticky">案件</th>
          <th class="sticky">確度</th><th class="sticky">状態</th><th class="sticky">開始週</th><th class="sticky">終了週</th>
          <th class="sticky">総額報酬<br><span style="font-size:10px;color:#8893a8">(万)</span></th>
          <th class="sticky">月額報酬<br><span style="font-size:10px;color:#8893a8">(万)</span></th>
          <th class="sticky">平均単価(月額)<br><span style="font-size:10px;color:#8893a8">(万/100%)</span></th>
          <th class="sticky">平均FTE</th><th class="sticky">アサイン</th><th class="sticky"></th>
        </tr>
        {rows}
      </table></div>
      <button class="btn sec" type="submit" style="font-size:12px;color:#c53030;margin-top:8px">🗑 選択したDeliveryを削除</button>
      </form>
      {_empty_cleanup}
      <form method="post" action="/deliveries/new" style="margin-top:14px;display:flex;gap:8px;align-items:center;flex-wrap:wrap;border-top:1px solid #eee;padding-top:12px">
        <span class="muted" style="font-size:12px">手動で追加:</span>
        <input type="text" id="dvNewDealFilter" placeholder="🔍 会社名・案件名で絞り込み" autocomplete="off"
          oninput="_deb('dvNewDealFilterFn')" style="font-size:12px;max-width:220px">
        <select name="deal_id" id="dvNewDealSelect" required style="font-size:12px;max-width:420px"><option value="">商談を選択（提案以降）</option>{_cand_opts}</select>
        <select name="confidence_override" style="font-size:12px">{_delivery_new_confidence_opts()}</select>
        <button class="btn sec" style="font-size:12px">＋Delivery追加</button>
      </form>
    </div>
    <script>
    function dvNewDealFilterFn() {{ filterSelectOptions('dvNewDealSelect', 'dvNewDealFilter'); }}
    function dvField(id, field, value){{
      fetch('/delivery/'+id+'/field',{{method:'POST',
        headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
        body:'field='+encodeURIComponent(field)+'&value='+encodeURIComponent(value)}})
      .then(function(r){{return r.json();}}).catch(function(){{}});
    }}
    function dvToggleAll(el){{
      // フィルタで表示中の行のみ全選択/解除
      document.querySelectorAll('#dv_bulk tr.dv-row').forEach(function(row){{
        if(row.style.display==='none') return;
        var cb=row.querySelector('input[name=ids]'); if(cb) cb.checked=el.checked;
      }});
    }}
    function filterDeliveries(){{
      var q=(document.getElementById('dvSearch').value||'').toLowerCase();
      var st=document.getElementById('dvStatusF').value, cf=document.getElementById('dvConfF').value;
      var bl1=document.getElementById('dvBizL1F').value, bl2=document.getElementById('dvBizL2F').value;
      var n=0;
      document.querySelectorAll('#dv_bulk tr.dv-row').forEach(function(row){{
        var ok=(!q||row.dataset.search.indexOf(q)>=0)&&(!st||row.dataset.status===st)&&(!cf||row.dataset.conf===cf)
          &&(!bl1||row.dataset.bizl1===bl1)&&(!bl2||row.dataset.bizl2===bl2);
        row.style.display=ok?'':'none'; if(ok)n++;
      }});
      var c=document.getElementById('dvCount'); if(c)c.textContent=n+'件';
      var all=document.getElementById('dvAll'); if(all) all.checked=false;  // フィルタ変更で全選択はリセット
    }}
    document.addEventListener('DOMContentLoaded',filterDeliveries);
    </script>"""


def _delivery_row_fields(owners: list, b: dict, dv: dict) -> str:
    """アサイン1行分の入力フィールド群（役割→区分(内部/外部)→メンバー(sel/txt)→期間→請求→実想定→メモ→責任者/担当者）。
    追加/編集の両方で使う。週入力は class=wkdate（JSで月曜スナップ）。
    責任者/担当者はこの行のメンバーをチェックボックスで指定する（2026-08-29。排他はJS側で制御し、
    ajaxで/delivery/{id}/fieldへ即時保存。値のバリデーションと参照切れクリアはサーバ側でも行う）。"""
    kind = b.get("member_kind") or "内部"
    owner = b.get("owner") or ""
    _bill = b.get("fte_billing")
    _bill = b.get("fte_pct") if _bill is None else _bill
    kind_opts = "".join(f'<option value="{k}"{" selected" if k == kind else ""}>{k}</option>'
                        for k in ("内部", "外部"))
    sel_disp = "display:none" if kind == "外部" else ""
    txt_disp = "" if kind == "外部" else "display:none"
    _resp_checked = " checked" if owner and owner == (dv.get("responsible_owner") or "") else ""
    _handle_checked = " checked" if owner and owner == (dv.get("handling_owner") or "") else ""
    return (
        f'<label style="font-size:11px">役割<br><input type="text" name="role" value="{_esc(b.get("role") or "")}" placeholder="PM/エンジニア等" style="width:110px"></label>'
        f'<label style="font-size:11px">区分<br><select name="member_kind" class="mkind" onchange="tglMember(this)" style="font-size:12px">{kind_opts}</select></label>'
        f'<label style="font-size:11px">メンバー<br>'
        f'<select name="owner_sel" class="mint" style="font-size:12px;{sel_disp}">{_opt(owners, owner if kind != "外部" else None)}</select>'
        f'<input type="text" name="owner_txt" class="mext" placeholder="外部メンバー名" value="{_esc(owner if kind == "外部" else "")}" style="width:120px;{txt_disp}"></label>'
        f'<label style="font-size:11px">開始週<br><input type="date" class="wkdate" name="from_week" value="{_esc(b.get("from_week") or "")}"></label>'
        f'<label style="font-size:11px">終了週<br><input type="date" class="wkdate" name="to_week" value="{_esc(b.get("to_week") or "")}"></label>'
        f'<label style="font-size:11px">稼働率(請求)%<br><input type="number" name="fte_billing" min="0" max="300" step="5" value="{_num_pct(_bill)}" style="width:80px"></label>'
        f'<label style="font-size:11px">稼働率(実想定)%<br><input type="number" name="fte_pct" min="0" max="300" step="5" value="{_num_pct(b.get("fte_pct"))}" style="width:80px"></label>'
        f'<label style="font-size:11px">メモ<br><input type="text" name="note" value="{_esc(b.get("note") or "")}" style="width:130px"></label>'
        f'<label style="font-size:11px;text-align:center">責任者<br>'
        f'<input type="checkbox" data-role-field="responsible_owner"{_resp_checked} onchange="dvOwnerRoleToggle(\'responsible_owner\',this)"></label>'
        f'<label style="font-size:11px;text-align:center">担当者<br>'
        f'<input type="checkbox" data-role-field="handling_owner"{_handle_checked} onchange="dvOwnerRoleToggle(\'handling_owner\',this)"></label>'
    )


def _delivery_cashflow_table_html(con, delivery_id: int) -> str:
    """月別入金計画テーブル（月が横軸、検収額(入力)/入金額(算出)が縦軸）。#75外注費に続く2026-08機能。
    3行(月ヘッダ/検収額/入金額)の縦のズレ防止のため、データ列は全てtext-align:centerに統一する
    （th既定=center・td既定=left・right指定と混在させると同じ列でも行ごとに水平位置が変わり、
    縦に並べた時にガタついて見える：ユーザー報告2026-08-24）。
    JS側のライブ再計算（dvCashflowRecalc、リロード無しで検収額入力→入金額表示を即時更新するため）が
    月を突き止められるよう、各セルに data-month 属性を付ける。"""
    cf = sfa_db.delivery_cashflow(con, delivery_id)
    months = cf["months"]
    if not months:
        return '<p class="muted" style="font-size:11px">開始週/終了週を設定すると月が表示されます。</p>'
    _th = 'style="font-size:11px;padding:4px 8px;white-space:nowrap;text-align:center"'
    head = "".join(f'<th data-month="{m}" {_th}>{_fmt_month(m)}</th>' for m in months)
    receipt_cells = "".join(
        f'<td style="padding:2px 4px;text-align:center"><input type="number" step="0.1" min="0" '
        f'data-month="{m}" id="dvRc_{delivery_id}_{m}" style="width:80px;text-align:center;box-sizing:border-box" '
        f'value="{"" if cf["receipts"].get(m) is None else cf["receipts"][m]}" '
        f'onchange="dvReceiptSet({delivery_id},\'{m}\',this.value)"></td>'
        for m in months)
    def _pay_disp(m):
        v = cf["payments"].get(m)
        return f'{v:,.1f}' if v is not None else '<span class="muted">—</span>'
    payment_cells = "".join(
        f'<td data-month="{m}" id="dvPy_{delivery_id}_{m}" '
        f'style="text-align:center;padding:4px 8px;white-space:nowrap">{_pay_disp(m)}</td>'
        for m in months)
    return (
        '<div style="overflow:auto"><table style="border-collapse:collapse">'
        f'<tr><th style="text-align:left;font-size:11px;padding:4px 8px;white-space:nowrap">月</th>{head}</tr>'
        f'<tr><th style="text-align:left;font-size:11px;padding:4px 8px;white-space:nowrap">検収額(万)</th>{receipt_cells}</tr>'
        f'<tr><th style="text-align:left;font-size:11px;padding:4px 8px;white-space:nowrap">入金額(万)</th>{payment_cells}</tr>'
        '</table></div>')


def delivery_form(con, delivery_id: int) -> str:
    """1Deliveryの編集：ヘッダ（週数・体制）＋アサイン（役割/区分/メンバー）＋プレビュー。#75。"""
    dv = sfa_db.get_delivery(con, delivery_id)
    if not dv:
        return '<div class="card"><p>Deliveryが見つかりません。<a href="/deliveries">← 一覧</a></p></div>'
    lbl, col = _delivery_confidence(dv.get("deal_stage") or "", dv.get("deal_status") or "open", dv.get("confidence_override"))
    status_opts = _opt(sfa_db.DELIVERY_STATUSES, dv.get("status") or "進行中")
    # 確度の手修正（自動＝商談ステージ連動に対する上書き。空選択=自動に戻す）。
    _auto_conf = sfa_db.delivery_confidence_auto(dv.get("deal_stage") or "", dv.get("deal_status") or "open")
    _conf_override = dv.get("confidence_override") or ""
    conf_opts = f'<option value=""{" selected" if not _conf_override else ""}>{_esc(_auto_conf)}（自動判定）</option>' + "".join(
        f'<option value="{_esc(c)}"{" selected" if _conf_override == c else ""}>{_esc(c)}</option>'
        for c in sfa_db.DELIVERY_CONFIDENCE_LEVELS)
    # 総アサイン工数(%/月)。実想定=稼働負荷表示用。請求ベース(請求未入力行は実想定)=平均単価の分母。
    _assign_effort = sfa_db.delivery_total_assign_effort(con, delivery_id)
    _assign_effort_bill = sfa_db.delivery_total_assign_effort(con, delivery_id, use_billing=True)
    _owners = sfa_db.get_master_list(con, "owners") or list(sfa_db.OWNERS)  # マスタ優先（後追加メンバーも反映）
    # 現在の週数（開始/終了が両方あれば算出）
    _weeks_val = ""
    try:
        if dv.get("start_week") and dv.get("end_week"):
            _weeks_val = str((date.fromisoformat(dv["end_week"]) - date.fromisoformat(dv["start_week"])).days // 7 + 1)
    except Exception:  # noqa: BLE001
        _weeks_val = ""
    # 体制（役割の並び順）を先に取得。アサインはこの並びに合わせて表示する。
    roles = sfa_db.list_delivery_roles(con, delivery_id)
    _role_order = {r["role"]: i for i, r in enumerate(roles)}
    # 既存ブロック（各行を編集フォーム＝入力で自動保存）。体制の役割順→役割名→idで整列。
    blocks = sfa_db.list_delivery_assignments(con, delivery_id)
    blocks.sort(key=lambda b: (_role_order.get(b.get("role") or "", 10_000),
                               b.get("role") or "￿", b.get("id") or 0))
    # #134: 必須項目チェック（商談がクロージング以降になってから注意喚起。個別画面はここ、一覧はdeliveries_page）。
    _missing = _delivery_missing_requirements(con, dv, assignments=blocks)
    _missing_banner = ""
    if _missing:
        _missing_items = "".join(f"<li>{_esc(m)}</li>" for m in _missing)
        _missing_banner = (
            '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:8px 12px;margin:0 0 12px">'
            '<p style="margin:0 0 4px;font-size:12px;color:#92400e;font-weight:600">⚠️ 未入力の必須項目があります'
            '（商談がクロージング以降のため）</p>'
            f'<ul style="margin:0 0 4px;padding-left:18px;font-size:12px;color:#92400e">{_missing_items}</ul>'
            '<p class="muted" style="margin:0;font-size:10px">※このチェックは表示時点の情報に基づきます。'
            '入力後は画面を再読み込みすると最新の状態に更新されます。</p>'
            '</div>')
    bedit = ""
    for b in blocks:
        bedit += f"""
        <form method="post" action="/delivery/{delivery_id}/assignment/{b['id']}/update" class="asgForm"
              style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;border:1px solid #e6e9f0;border-radius:8px;padding:8px;margin-bottom:6px">
          {_delivery_row_fields(_owners, b, dv)}
          <span class="asgSaved" style="font-size:10px;color:#94a3b8;align-self:center">自動保存</span>
          <button formaction="/delivery/{delivery_id}/assignment/{b['id']}/delete" formnovalidate
                  class="btn sec" style="font-size:11px;color:#c53030"
                  onclick="return confirm('このアサインを削除しますか？')">×削除</button>
        </form>"""
    if not bedit:
        bedit = '<p class="muted">まだアサインがありません。体制で役割を追加するか、各役割の「複製」で行を増やせます。</p>'
    # プレビューグリッド（実想定を主に色付け・請求は小さく併記）。行の並びは体制の役割順に合わせる。
    grid = sfa_db.delivery_grid(con, delivery_id)
    _own_role_idx = {}
    for b in blocks:
        _ow = b.get("owner") or ""
        _idx = _role_order.get(b.get("role") or "", 10_000)
        if _ow not in _own_role_idx or _idx < _own_role_idx[_ow]:
            _own_role_idx[_ow] = _idx
    if grid["weeks"]:
        grid["owners"] = sorted(grid["owners"], key=lambda o: (_own_role_idx.get(o, 10_000), o))
        head = "".join(f'<th style="font-size:11px;white-space:nowrap">{_fmt_week(w)}</th>' for w in grid["weeks"])
        grows = ""
        for ow in grid["owners"]:
            cells = ""
            for w in grid["weeks"]:
                cv = grid["cells"].get(ow, {}).get(w) or {}
                a = cv.get("actual", 0)
                bil = cv.get("billing", 0)
                if a or bil:
                    _sub = (f'<br><span style="font-size:9px;opacity:.7">請{_num_pct(bil)}</span>'
                            if abs((bil or 0) - (a or 0)) > 0.01 else "")
                    inner = f'{_num_pct(a)}%{_sub}'
                else:
                    inner = "·"
                cells += f'<td style="text-align:center;{_heat_style(a)}">{inner}</td>'
            grows += f'<tr><th style="text-align:left;white-space:nowrap">{_esc(ow)}</th>{cells}</tr>'
        grid_html = (f'<div style="overflow:auto"><table style="border-collapse:collapse">'
                     f'<tr><th></th>{head}</tr>{grows}</table></div>'
                     '<p class="muted" style="font-size:11px;margin:6px 0 0">※色は<b>実想定</b>基準。請求が実想定と異なる週は小さく「請◯」を併記。'
                     'このグリッドはこのDelivery分のみ。全社の総工数（デモ開発＋Delivery＋ベース）と負荷色はHishoダッシュボードで見ます。</p>')
    else:
        grid_html = '<p class="muted">アサインを追加するとここに週別グリッドが表示されます。</p>'

    # 体制（役割ごとの目標稼働率）。役割の期間平均とアサインの期間平均の整合チェックに使う（rolesは上で取得済み）。
    role_targets = {}
    role_rows = ""
    for r in roles:
        _rb = r.get("fte_billing")
        _ra = r.get("fte_pct")
        role_targets[r["role"]] = {"b": _rb, "a": _ra}
        role_rows += f"""
        <form class="roleRow" method="post" action="/delivery/{delivery_id}/role/{r['id']}/update"
              data-role-id="{r['id']}"
              style="display:flex;gap:6px;flex-wrap:wrap;align-items:flex-end;border:1px solid #eef1f6;border-radius:6px;padding:6px;margin-bottom:5px;background:#fff">
          <span class="drag-handle" draggable="true" title="ドラッグで並び替え" style="cursor:grab;color:#aab;font-size:15px;line-height:1;align-self:center">⠿</span>
          <label style="font-size:11px">役割<br><input type="text" name="role" class="rRole" value="{_esc(r['role'])}" style="width:120px"></label>
          <label style="font-size:11px">目標(請求)%<br><input type="number" name="fte_billing" class="rTgtB" min="0" max="300" step="5" value="{_num_pct(_rb) if _rb is not None else ''}" style="width:74px"></label>
          <label style="font-size:11px">目標(実想定)%<br><input type="number" name="fte_pct" class="rTgtA" min="0" max="300" step="5" value="{_num_pct(_ra) if _ra is not None else ''}" style="width:74px"></label>
          <span style="font-size:11px;color:#64748b">現在(期間平均) 請<b class="curB">-</b>% / 実<b class="curA">-</b>%</span>
          <span class="asgSaved" style="font-size:10px;color:#94a3b8">自動保存</span>
          <button formaction="/delivery/{delivery_id}/role/{r['id']}/add-member" formnovalidate
                  class="btn sec" style="font-size:11px;color:#0e7490" title="この役割のアサイン行を複製（空メンバーで追加）">複製</button>
          <button formaction="/delivery/{delivery_id}/role/{r['id']}/delete" formnovalidate
                  class="btn sec" style="font-size:11px;color:#c53030"
                  onclick="return confirm('この役割を体制から削除します。対応するアサイン行も削除されます。よろしいですか？')">×</button>
        </form>"""
    if not role_rows:
        role_rows = '<p class="muted" style="font-size:11px">体制未設定。下で役割を追加すると、その役割のアサイン行が自動生成されます。</p>'
    import json as _json
    role_targets_json = _json.dumps(role_targets, ensure_ascii=False)  # noqa: F841 (旧ハイライト用・保持)

    return f"""
    <div class="card">
      <p style="margin:0 0 8px"><a href="/deliveries">← Delivery一覧</a></p>
      <h2 style="margin:0 0 2px">{_esc(dv.get("title") or "(無題)")}
        <span style="background:{col};color:#fff;border-radius:5px;padding:1px 8px;font-size:12px;vertical-align:middle">{lbl}</span></h2>
      <p class="muted" style="margin:0 0 12px">
        <a href="/deal/{dv["deal_id"]}">{_esc(dv.get("account_name") or "")}：{_esc(dv.get("deal_name") or "")}</a>
        （ステージ: {_esc(dv.get("deal_stage") or "")}）</p>
      {_missing_banner}
      <div style="margin:-4px 0 14px">
        <form method="post" action="/delivery/{delivery_id}/duplicate" style="display:inline;margin:0"
          onsubmit="return confirm('このDeliveryを複製します（体制の目標役割・報酬/外注費設定は引き継ぎ、アサインの実績・検収実額・確度の手動固定は引き継ぎません）。よろしいですか？')">
          <button class="btn sec" type="submit">📋 このDeliveryを複製</button>
        </form>
      </div>

      <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:stretch;margin-bottom:14px">
        <div style="flex:1 1 380px;min-width:340px;border:1px solid #e6e9f0;border-radius:8px;padding:12px;display:flex;flex-direction:column">
          <h3 style="margin:0 0 4px;font-size:14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">基礎情報
            <button class="btn" form="dvBaseForm" style="font-size:12px">保存</button>
            <span id="dvBaseSaveStatus" class="muted" style="font-size:11px;font-weight:normal">入力すると自動保存されます</span>
          </h3>
          <p style="margin:0 0 8px;font-size:11px;color:#92400e;background:#fffbeb;border:1px solid #fde68a;border-radius:6px;padding:4px 8px">
            ⚠️ 他の項目（体制・アサイン等）より先に、まず基礎情報を入力してください（必須）。自動保存されますが、押し忘れが不安な場合はこの「保存」を押してください。</p>
          <form id="dvBaseForm" method="post" action="/delivery/{delivery_id}/save" style="display:flex;flex-direction:column;flex:1">
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end">
              <label style="font-size:12px">案件名<br><input type="text" name="title" value="{_esc(dv.get("title") or "")}" style="width:200px"></label>
              <label style="font-size:12px">週数<br><input type="number" id="hdrWeeks" min="1" max="104" value="{_weeks_val}" style="width:60px" oninput="hdrCalcEnd();dvFeeRecalc();dvCostRecalc()"></label>
              <label style="font-size:12px">開始週(月曜)<br><input type="date" class="wkdate" id="hdrStart" name="start_week" value="{_esc(dv.get("start_week") or "")}" onchange="hdrCalcEnd();dvFeeRecalc();dvCostRecalc()"></label>
              <label style="font-size:12px">終了週(月曜)<br><input type="date" class="wkdate" id="hdrEnd" name="end_week" value="{_esc(dv.get("end_week") or "")}" onchange="dvFeeRecalc();dvCostRecalc()"></label>
              <label style="font-size:12px">状態<br><select name="status">{status_opts}</select></label>
            </div>
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:8px">
              <label style="font-size:12px">確度<br><select name="confidence_override">{conf_opts}</select></label>
              <label style="font-size:12px">事業種別L1<br><select name="business_type_l1_override">{_delivery_biz_l1_opts(con, dv)}</select></label>
              <label style="font-size:12px">事業種別L2<br><select name="business_type_l2_override">{_delivery_biz_l2_opts(con, dv)}</select></label>
            </div>
            <p class="muted" style="font-size:10px;margin:4px 0 0">※事業種別 未選択＝商談の事業種別を継承。1商談から複数Deliveryが分かれる場合など、Deliveryごとに個別指定したい時だけ選んでください。</p>
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:8px">
              <label style="font-size:12px">報酬形態<br>
                <select id="dvFeeMode" name="fee_mode" onchange="dvFeeModeChanged()">
                  <option value="monthly"{" selected" if (dv.get("fee_mode") or "monthly") != "total" else ""}>月額報酬</option>
                  <option value="total"{" selected" if (dv.get("fee_mode") or "monthly") == "total" else ""}>総額報酬</option>
                </select></label>
              <label style="font-size:12px">報酬額/月額(万)<br>
                <input type="number" step="0.1" min="0" id="dvFeeMonthly" name="fee_monthly" style="width:110px"
                       value="{"" if dv.get("fee_monthly") is None else dv.get("fee_monthly")}" oninput="dvFeeFieldInput(this)"></label>
              <label style="font-size:12px">報酬額/総額(万)<br>
                <input type="number" step="0.1" min="0" id="dvFeeTotal" name="fee_total" style="width:110px"
                       value="{"" if dv.get("fee_total") is None else dv.get("fee_total")}" oninput="dvFeeFieldInput(this)"></label>
              <label style="font-size:12px">成果報酬有無<br>
                <select id="dvPerfFee" name="performance_fee" onchange="dvPerfFeeChanged()">{_delivery_performance_fee_opts(dv.get("performance_fee"))}</select></label>
              <label style="font-size:12px">成果報酬比率(%)<br>
                <input type="number" step="0.1" min="0" max="100" id="dvPerfFeeRatio" name="performance_fee_ratio" style="width:90px"
                       value="{"" if dv.get("performance_fee_ratio") is None else dv.get("performance_fee_ratio")}" oninput="dvPerfFeeChanged()"></label>
            </div>
            <p class="muted" style="font-size:11px;margin:2px 0 0" id="dvFeeMonths"></p>
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:8px">
              <label style="font-size:12px">外注先<br>
                <input type="text" id="dvCostVendor" name="cost_vendor" style="width:140px"
                       value="{_esc(dv.get("cost_vendor") or "")}"></label>
              <label style="font-size:12px">外注費形態<br>
                <select id="dvCostMode" name="cost_mode" onchange="dvCostModeChanged()">
                  <option value="monthly"{" selected" if (dv.get("cost_mode") or "monthly") != "total" else ""}>月額</option>
                  <option value="total"{" selected" if (dv.get("cost_mode") or "monthly") == "total" else ""}>総額</option>
                </select></label>
              <label style="font-size:12px">外注費/月額(万)<br>
                <input type="number" step="0.1" min="0" id="dvCostMonthly" name="cost_monthly" style="width:110px"
                       value="{"" if dv.get("cost_monthly") is None else dv.get("cost_monthly")}" oninput="dvCostFieldInput(this)"></label>
              <label style="font-size:12px">外注費/総額(万)<br>
                <input type="number" step="0.1" min="0" id="dvCostTotal" name="cost_total" style="width:110px"
                       value="{"" if dv.get("cost_total") is None else dv.get("cost_total")}" oninput="dvCostFieldInput(this)"></label>
              <span class="muted" style="font-size:11px;align-self:center" id="dvCostMonths"></span>
            </div>
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:8px">
              <label style="font-size:12px">請求方法<br><select name="billing_method">{_delivery_billing_method_opts(con, dv.get("billing_method"))}</select></label>
              <label style="font-size:12px">請求期日<br>{_delivery_billing_due_html(con, dv)}</label>
              <label style="font-size:12px">請求送付先<br>
                <input type="text" name="billing_recipient" placeholder="例: 経理部佐藤さん、PF提出" style="width:220px"
                       value="{_esc(dv.get("billing_recipient") or "")}"></label>
            </div>
            <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:8px">
              <label style="font-size:12px">経費請求有無<br><select name="expense_billing">{_delivery_expense_billing_opts(dv.get("expense_billing"))}</select></label>
              <label style="font-size:12px">経費請求メモ<br>
                <input type="text" name="expense_billing_note" style="width:220px"
                       value="{_esc(dv.get("expense_billing_note") or "")}"></label>
            </div>
            <details style="margin-top:8px;padding:8px 10px;background:#f8fafc;border-radius:8px">
              <summary style="cursor:pointer;font-size:12px;color:#2563eb">総アサイン工数・平均単価・想定利益を表示</summary>
              <div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:8px">
                <div style="font-size:12px">総アサイン工数<br><b id="dvEffort" style="font-size:15px">{_assign_effort:g}</b> <span class="muted">%/月</span>
                  <span class="muted" style="font-size:10px">（請求 <b id="dvEffortBill">{f'{_assign_effort_bill:g}' if _assign_effort_bill > 0 else '-'}</b>%/月）</span></div>
                <div style="font-size:12px">平均単価(月額)<br><b id="dvUnitPrice" style="font-size:15px">—</b> <span class="muted">万円/100%</span></div>
                <div style="font-size:12px">想定利益(月額/総額)<br><b id="dvProfitMonthly" style="font-size:15px">—</b> / <b id="dvProfitTotal" style="font-size:15px">—</b> <span class="muted">万円</span>
                  <span class="muted" style="font-size:10px">（報酬額－外注費）</span></div>
                <div class="muted" style="font-size:10px;align-self:center;max-width:320px">※総アサイン工数＝Σ(アサイン週数×稼働率)÷総期間週数（＝期間平均の合計稼働率）。請求は純粋な請求稼働（0%＝成果物ベースで稼働コミットなし＝「-」）。平均単価(月額)＝<b>月額報酬</b>÷総工数×100（請求ベース優先・請求0%は実想定で試算）を万円単位・10万円未満四捨五入で表示。アサイン編集後は保存して再読込で更新。</div>
              </div>
            </details>
            <label style="font-size:12px;display:flex;flex-direction:column;flex:1;margin-top:8px">概要・納品方針
              <textarea name="overview" style="width:100%;flex:1;min-height:60px;margin-top:2px">{_esc(dv.get("overview") or "")}</textarea></label>
            <p class="muted" style="font-size:11px;margin:4px 0 0">※基礎情報は各項目の入力後（フォーカスを外した時点）で自動保存されます。「保存」ボタンは押し忘れても問題ありません
              （週数/開始週/終了週の変更のみ、アサイン週の連動再計算のため保存後に自動で再読込します）。
              週は月曜に自動スナップ。週数＋開始週で終了週を自動計算。開始/終了週は体制「複製」で生成する行の初期値（ガイド）です。
              月額/総額は自動換算されますが、灰色側を直接編集すると手修正として保持されます（報酬形態を切り替えると自動換算に戻ります）。</p>
          </form>
        </div>
        <div style="flex:1 1 380px;min-width:340px;display:flex;flex-direction:column;gap:14px">
          <div style="border:1px solid #e6e9f0;border-radius:8px;padding:12px;display:flex;flex-direction:column">
            <h3 style="margin:0 0 6px;font-size:14px">責任者・担当者</h3>
            <p class="muted" style="font-size:11px;margin:0 0 8px">下の「アサイン」各行のチェックボックスで指定します（自動表示のみ）。</p>
            <div id="dvOwnerRolesBox" style="display:flex;gap:14px;flex-wrap:wrap">{_delivery_owner_roles_box_html(dv)}</div>
          </div>
          <div style="flex:1;border:1px solid #e6e9f0;border-radius:8px;padding:12px;display:flex;flex-direction:column">
            <h3 style="margin:0 0 6px;font-size:14px">体制（役割別の目標稼働率）</h3>
            <p class="muted" style="font-size:11px;margin:0 0 6px">役割を追加すると、その役割のアサイン行が自動生成されます。削除すると、対応するアサイン行も削除されます。
              各行は編集して「保存」。役割ごとの<b>目標</b>と、アサインした人の<b>合計</b>が一致しないと、該当欄が黄色くハイライトされます。⠿をドラッグすると並び替えられます。</p>
            <form method="post" action="/delivery/{delivery_id}/role/add"
                  style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;background:#f8fafc;border-radius:8px;padding:8px;margin-bottom:8px">
              <label style="font-size:11px">役割<br><input type="text" name="role" required placeholder="PM/エンジニア等" style="width:130px"></label>
              <label style="font-size:11px">目標(請求)%<br><input type="number" name="fte_billing" min="0" max="300" step="5" value="100" style="width:76px"></label>
              <label style="font-size:11px">目標(実想定)%<br><input type="number" name="fte_pct" min="0" max="300" step="5" value="100" style="width:76px"></label>
              <button class="btn sec" style="font-size:12px">＋役割追加（アサイン行も生成）</button>
            </form>
            <div id="dvRoleRows" style="overflow:auto">{role_rows}</div>
          </div>
        </div>
      </div>

      <h3 style="margin:16px 0 6px;font-size:14px">アサイン（役割 × 区分 × メンバー × 期間 × 稼働率）</h3>
      <p class="muted" style="font-size:11px;margin:0 0 8px">稼働率は<b>請求</b>（クライアント請求上）と<b>実想定</b>（実稼働・負荷計算はこちら）。区分「外部」でメンバーを自由記述。<b>入力すると自動保存</b>されます。行の追加は体制の「複製」から。並びは体制の役割順。</p>
      {bedit}

      <h3 style="margin:16px 0 6px;font-size:14px">プレビュー（週別・このDelivery分）</h3>
      <div id="dvPreview">{grid_html}</div>

      <h3 style="margin:16px 0 6px;font-size:14px">月別入金計画（検収額→入金額）</h3>
      <p class="muted" style="font-size:11px;margin:0 0 8px">月額/総額報酬を均した換算では実際の入金月がズレるため、月ごとの検収額(万円)を実額で入力すると、
        支払いサイクル分ずらした月の入金額として算出されます。xlsx出力（Delivery一覧の一括抽出）にも同テーブルが出ます。</p>
      <label style="font-size:12px">支払いサイクル<br>
        <input type="number" min="0" max="24" id="dvPayCycle" style="width:70px"
               value="{int(dv.get("payment_cycle_months") if dv.get("payment_cycle_months") is not None else 1)}"
               onchange="dvSetCycle({delivery_id}, this.value)"> ヶ月後に入金（検収した月を0として。既定=1＝翌月）</label>
      <div id="dvCashflow" style="margin-top:8px">{_delivery_cashflow_table_html(con, delivery_id)}</div>

      <div style="margin-top:18px;border-top:1px solid #eee;padding-top:10px">
        <form method="post" action="/delivery/{delivery_id}/delete" style="display:inline"
              onsubmit="return confirm('このDelivery案件を削除します。アサインも消えます。よろしいですか？')">
          <button class="btn sec" style="font-size:12px;color:#c53030">このDeliveryを削除</button></form>
      </div>
    </div>
    <script>
    function _mondayOf(s){{ if(!s) return ''; var p=String(s).split('-'); if(p.length!==3) return s;
      var d=new Date(+p[0], +p[1]-1, +p[2]); if(isNaN(d)) return s;
      var wd=(d.getDay()+6)%7; d.setDate(d.getDate()-wd);
      return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }}
    function snapWk(el){{ if(el.value) el.value=_mondayOf(el.value); }}
    function hdrCalcEnd(){{ var w=parseInt(document.getElementById('hdrWeeks').value,10),
      s=document.getElementById('hdrStart').value, e=document.getElementById('hdrEnd');
      if(!(w>0)||!s) return; var mo=_mondayOf(s); var p=mo.split('-');
      var d=new Date(+p[0], +p[1]-1, +p[2]); d.setDate(d.getDate()+(w-1)*7);
      e.value=d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }}
    function _dvFeeMonths(){{ var s=document.getElementById('hdrStart').value,
      e=document.getElementById('hdrEnd').value; if(!s||!e) return 0;
      var sd=new Date(s), ed=new Date(e); var days=Math.round((ed-sd)/86400000);
      if(isNaN(days)||days<0) return 0;
      var weeks=Math.floor(days/7)+1; return weeks/4; }}  /* 月数=合計週数÷4(≒1ヶ月)で統一 */
    /* 月額/総額の自動換算＋手修正（新規タスク）: 従来はreadOnlyで灰色側を編集不可にしていたが、
       灰色側（自動算出される方）を直接編集した場合はdata-manual='1'を立てて手修正として保持する
       （以後、報酬形態を切り替えるまで自動換算で上書きしない）。 */
    function dvFeeRecalc(){{
      var modeEl=document.getElementById('dvFeeMode'); if(!modeEl) return;
      var mode=modeEl.value, m=_dvFeeMonths();
      var mo=document.getElementById('dvFeeMonthly'), to=document.getElementById('dvFeeTotal');
      var note=document.getElementById('dvFeeMonths');
      if(note) note.textContent = m ? ('期間 '+(+m.toFixed(2))+'ヶ月で換算（合計週数÷4）') : '開始/終了週を入れると換算';
      var ro='#f1f5f9';
      if(mode==='total'){{
        to.style.background='';
        mo.style.background = (mo.dataset.manual==='1') ? '' : ro;
        if(m && to.value!=='' && mo.dataset.manual!=='1') mo.value=Math.round((parseFloat(to.value)/m)*100)/100;
      }} else {{
        mo.style.background='';
        to.style.background = (to.dataset.manual==='1') ? '' : ro;
        if(m && mo.value!=='' && to.dataset.manual!=='1') to.value=Math.round((parseFloat(mo.value)*m)*100)/100;
      }}
      // 平均単価(月額)＝月額報酬(円)÷(工数÷100)。工数は請求ベース優先、請求0%(成果物ベース)なら実想定。
      // 表示は万円単位・10万円未満を四捨五入（例: 月額244万・請求120%/月→200万／請求0%は実想定80で試算）。
      var effAEl=document.getElementById('dvEffort'), effBEl=document.getElementById('dvEffortBill'),
          upEl=document.getElementById('dvUnitPrice');
      if(upEl){{
        var effA=parseFloat(effAEl&&effAEl.textContent)||0, effB=parseFloat(effBEl&&effBEl.textContent)||0;
        var effP=effB>0?effB:effA, mon=parseFloat(mo.value)||0;
        upEl.textContent = (effP>0 && mon>0)
          ? (Math.round(mon*10000*100/effP/100000)*10).toLocaleString() : '—';
      }}
      dvProfitRecalc();
    }}
    function dvFeeFieldInput(el){{
      var modeEl=document.getElementById('dvFeeMode');
      var mode=modeEl?modeEl.value:'monthly';
      var isMaster=(mode==='monthly' && el.id==='dvFeeMonthly')||(mode==='total' && el.id==='dvFeeTotal');
      if(!isMaster){{ el.dataset.manual='1'; }}
      dvFeeRecalc();
    }}
    function dvFeeModeChanged(){{
      var mo=document.getElementById('dvFeeMonthly'), to=document.getElementById('dvFeeTotal');
      mo.dataset.manual=''; to.dataset.manual='';
      dvFeeRecalc();
    }}
    /* 外注費（報酬額と同じ月額/総額の自動換算＋手修正の仕組み）。 */
    function dvCostRecalc(){{
      var modeEl=document.getElementById('dvCostMode'); if(!modeEl) return;
      var mode=modeEl.value, m=_dvFeeMonths();
      var mo=document.getElementById('dvCostMonthly'), to=document.getElementById('dvCostTotal');
      var note=document.getElementById('dvCostMonths');
      if(note) note.textContent = m ? ('期間 '+(+m.toFixed(2))+'ヶ月で換算（合計週数÷4）') : '開始/終了週を入れると換算';
      var ro='#f1f5f9';
      if(mode==='total'){{
        to.style.background='';
        mo.style.background = (mo.dataset.manual==='1') ? '' : ro;
        if(m && to.value!=='' && mo.dataset.manual!=='1') mo.value=Math.round((parseFloat(to.value)/m)*100)/100;
      }} else {{
        mo.style.background='';
        to.style.background = (to.dataset.manual==='1') ? '' : ro;
        if(m && mo.value!=='' && to.dataset.manual!=='1') to.value=Math.round((parseFloat(mo.value)*m)*100)/100;
      }}
      dvProfitRecalc();
    }}
    function dvCostFieldInput(el){{
      var modeEl=document.getElementById('dvCostMode');
      var mode=modeEl?modeEl.value:'monthly';
      var isMaster=(mode==='monthly' && el.id==='dvCostMonthly')||(mode==='total' && el.id==='dvCostTotal');
      if(!isMaster){{ el.dataset.manual='1'; }}
      dvCostRecalc();
    }}
    function dvCostModeChanged(){{
      var mo=document.getElementById('dvCostMonthly'), to=document.getElementById('dvCostTotal');
      mo.dataset.manual=''; to.dataset.manual='';
      dvCostRecalc();
    }}
    // 請求期日:「他」を選ぶと自由入力欄を出す（ユーザー要望2026-08-28）。
    function dvBillingDueChanged(){{
      var sel=document.getElementById('dvBillingDueSel'), other=document.getElementById('dvBillingDueOther');
      if(!sel||!other) return;
      other.style.display = sel.value==='{_DELIVERY_BILLING_DUE_OTHER}' ? '' : 'none';
    }}
    // 成果報酬有無=「有」の場合のみ比率入力を必須にする（ユーザー要望2026-08-30）。
    // このアプリの自動保存はfetch経由でネイティブのフォームバリデーションを経由しないため、
    // required属性は「未入力なら赤枠で目立たせる」視覚的な注意喚起として使う（保存自体はブロックしない）。
    function dvPerfFeeChanged(){{
      var sel=document.getElementById('dvPerfFee'), ratio=document.getElementById('dvPerfFeeRatio');
      if(!sel||!ratio) return;
      var need = sel.value==='有';
      ratio.required = need;
      ratio.style.background = (need && ratio.value==='') ? '#fef3c7' : '';
    }}
    // 想定利益(月額/総額) = 報酬額－外注費。どちらも未入力なら「—」、片方だけ未入力は0扱い。
    function dvProfitRecalc(){{
      var pm=document.getElementById('dvProfitMonthly'), pt=document.getElementById('dvProfitTotal');
      if(!pm||!pt) return;
      var fm=document.getElementById('dvFeeMonthly'), ft=document.getElementById('dvFeeTotal'),
          cm=document.getElementById('dvCostMonthly'), ct=document.getElementById('dvCostTotal');
      var fmv=(fm&&fm.value!=='')?parseFloat(fm.value):null, ftv=(ft&&ft.value!=='')?parseFloat(ft.value):null;
      var cmv=(cm&&cm.value!=='')?parseFloat(cm.value):null, ctv=(ct&&ct.value!=='')?parseFloat(ct.value):null;
      pm.textContent = (fmv===null && cmv===null) ? '—' : Math.round(((fmv||0)-(cmv||0))*100)/100;
      pt.textContent = (ftv===null && ctv===null) ? '—' : Math.round(((ftv||0)-(ctv||0))*100)/100;
    }}
    // 月別入金計画: 保存はバックグラウンドで行い（レスポンスを待たない）、入金額表示は
    // その場でJS側で再計算する。以前はfetch完了後にlocation.reload()していたため、セルを
    // move（Tab/クリック）した直後にページ全体が再読込されてしまい、連続入力ができなかった
    // （ユーザー報告2026-08-24）。入金月が現在の表示列より先（表の右端より後ろ）に出る場合のみ、
    // その月の表示は次回ページ再読込まで反映されない（軽微な制約として許容）。
    function dvReceiptSet(id, month, value){{
      fetch('/delivery/'+id+'/receipt',{{method:'POST',
        headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
        body:'month='+encodeURIComponent(month)+'&amount='+encodeURIComponent(value)}}).catch(function(){{}});
      dvCashflowRecalc();
    }}
    function dvSetCycle(id, value){{
      fetch('/delivery/'+id+'/field',{{method:'POST',
        headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
        body:'field=payment_cycle_months&value='+encodeURIComponent(value)}}).catch(function(){{}});
      dvCashflowRecalc();
    }}
    function dvCashflowRecalc(){{
      var cont=document.getElementById('dvCashflow'); if(!cont) return;
      var cycleEl=document.getElementById('dvPayCycle');
      var cycle=cycleEl?(parseInt(cycleEl.value,10)||0):1;
      var pays={{}};
      cont.querySelectorAll('input[data-month]').forEach(function(el){{
        var v=parseFloat(el.value); if(!(v>0))return;
        var m=el.getAttribute('data-month'), p=m.split('-'), y=+p[0], mo=+p[1];
        var idx=y*12+(mo-1)+cycle, py=Math.floor(idx/12), pmo=(idx%12)+1;
        var pm=py+'-'+('0'+pmo).slice(-2);
        pays[pm]=(pays[pm]||0)+v;
      }});
      cont.querySelectorAll('td[data-month]').forEach(function(td){{
        var m=td.getAttribute('data-month');
        td.innerHTML = pays.hasOwnProperty(m) ? (Math.round(pays[m]*10)/10).toLocaleString()
                                              : '<span class="muted">—</span>';
      }});
    }}
    dvFeeRecalc();
    dvCostRecalc();
    dvPerfFeeChanged();
    function tglMember(sel){{ var f=sel.closest('form'); if(!f) return;
      var mi=f.querySelector('.mint'), me=f.querySelector('.mext');
      if(sel.value==='外部'){{ if(mi)mi.style.display='none'; if(me)me.style.display=''; }}
      else {{ if(mi)mi.style.display=''; if(me)me.style.display='none'; }} }}
    // 役割ごとの「期間平均」稼働率を算出（週別に積み上げ→在籍週で平均）。
    // 同じ役割で途中メンバー交代（重複期間なし）なら合計ではなく実効の平均になる。
    function roleWeeklyAvg(role){{
      var wk={{}};
      document.querySelectorAll('.asgForm').forEach(function(f){{
        var rl=f.querySelector('[name=role]'); if(!rl||rl.value.trim()!==role) return;
        var fw=(f.querySelector('[name=from_week]')||{{}}).value, tw=(f.querySelector('[name=to_week]')||{{}}).value;
        var a=parseFloat((f.querySelector('[name=fte_pct]')||{{}}).value)||0;
        var b=parseFloat((f.querySelector('[name=fte_billing]')||{{}}).value)||0;
        if(!fw||!tw) return; var p1=_mondayOf(fw).split('-'), p2=_mondayOf(tw).split('-');
        var d=new Date(+p1[0],+p1[1]-1,+p1[2]), e=new Date(+p2[0],+p2[1]-1,+p2[2]), g=0;
        while(d<=e && g<520){{ var k=d.getFullYear()+'_'+d.getMonth()+'_'+d.getDate();
          wk[k]=wk[k]||{{a:0,b:0}}; wk[k].a+=a; wk[k].b+=b; d.setDate(d.getDate()+7); g++; }}
      }});
      var ks=Object.keys(wk); if(!ks.length) return {{a:0,b:0,n:0}};
      var sa=0,sb=0; ks.forEach(function(k){{sa+=wk[k].a; sb+=wk[k].b;}});
      return {{a:sa/ks.length, b:sb/ks.length, n:ks.length}};
    }}
    function _r1(x){{ return Math.round(x*10)/10; }}
    function checkRoleTotals(){{
      document.querySelectorAll('.asgForm [name=fte_pct],.asgForm [name=fte_billing]').forEach(function(i){{i.style.background='';i.style.outline='';}});
      document.querySelectorAll('.roleRow').forEach(function(row){{
        var rInp=row.querySelector('.rRole'); var role=rInp?rInp.value.trim():'';
        var tbi=row.querySelector('.rTgtB'), tai=row.querySelector('.rTgtA');
        var tb=tbi&&tbi.value!==''?parseFloat(tbi.value):NaN;
        var ta=tai&&tai.value!==''?parseFloat(tai.value):NaN;
        var avg=roleWeeklyAvg(role);
        var cb=row.querySelector('.curB'), ca=row.querySelector('.curA');
        if(cb)cb.textContent=_r1(avg.b); if(ca)ca.textContent=_r1(avg.a);
        var hlB=!isNaN(tb)&&Math.abs(avg.b-tb)>0.01;
        var hlA=!isNaN(ta)&&Math.abs(avg.a-ta)>0.01;
        if(tbi)tbi.style.background=hlB?'#fef3c7':''; if(tai)tai.style.background=hlA?'#fef3c7':'';
        if(cb)cb.style.color=hlB?'#b45309':'inherit'; if(ca)ca.style.color=hlA?'#b45309':'inherit';
        if(hlA||hlB) document.querySelectorAll('.asgForm').forEach(function(f){{
          var rl=f.querySelector('[name=role]'); if(!rl||rl.value.trim()!==role||!role) return;
          if(hlB){{var i=f.querySelector('[name=fte_billing]'); if(i){{i.style.background='#fef3c7';i.style.outline='2px solid #f59e0b';}}}}
          if(hlA){{var i=f.querySelector('[name=fte_pct]'); if(i){{i.style.background='#fef3c7';i.style.outline='2px solid #f59e0b';}}}}
        }});
      }});
    }}
    function autoSave(form){{
      var st=form.querySelector('.asgSaved'); if(st){{st.textContent='保存中…';st.style.color='#94a3b8';}}
      var body=new URLSearchParams(new FormData(form)); body.set('ajax','1');
      fetch(form.action,{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}})
        .then(function(r){{ if(st){{st.textContent=r.ok?'保存済み':'保存失敗';st.style.color=r.ok?'#059669':'#b91c1c';}} }})
        .catch(function(){{ if(st){{st.textContent='保存失敗';st.style.color='#b91c1c';}} }});
    }}
    // 体制の役割をドラッグで並び替え（#168）。#masters_pageの.master-item並び替えと同じ方式。
    function initRoleDrag(deliveryId){{
      var container=document.getElementById('dvRoleRows'); if(!container) return;
      // ドラッグの起点は⠿ハンドルのみ（行全体をdraggableにすると、役割名/目標%の
      // 入力欄でテキスト選択できなくなるため、ハンドルだけをdraggable=trueにする）。
      container.querySelectorAll('.roleRow').forEach(function(row){{
        var handle=row.querySelector('.drag-handle'); if(!handle) return;
        handle.addEventListener('dragstart',function(e){{
          e.dataTransfer.effectAllowed='move'; container._dragging=row;
        }});
        row.addEventListener('dragover',function(e){{
          e.preventDefault();
          var dragging=container._dragging; if(!dragging||dragging===row) return;
          var rect=row.getBoundingClientRect();
          if(e.clientY<rect.top+rect.height/2) container.insertBefore(dragging,row);
          else container.insertBefore(dragging,row.nextSibling);
        }});
        handle.addEventListener('dragend',function(){{
          container._dragging=null;
          var ids=Array.from(container.querySelectorAll('.roleRow')).map(function(r){{return r.dataset.roleId;}});
          fetch('/delivery/'+deliveryId+'/roles/reorder',{{method:'POST',
            headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
            body:'order='+ids.join(',')}});
        }});
      }});
    }}
    function _heatJs(p){{ if(p<=0) return 'background:transparent;color:#cbd5e1';
      if(p<70) return 'background:#f0fdf4;color:#166534'; if(p<100) return 'background:#dcfce7;color:#166534';
      if(p<150) return 'background:#fef3c7;color:#92400e'; return 'background:#dc2626;color:#fff;font-weight:700'; }}
    function _esc3(s){{ return String(s).replace(/[&<>]/g,function(c){{return{{'&':'&amp;','<':'&lt;','>':'&gt;'}}[c];}}); }}
    function _isoAdd(iso,wks){{ var p=iso.split('-'); var d=new Date(+p[0],+p[1]-1,+p[2]); d.setDate(d.getDate()+wks*7);
      return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2); }}
    // クライアント側でプレビューを再構築（メンバー選択・稼働率の編集に即追従）。行=メンバー(未定は役割)。
    function renderPreview(){{
      var box=document.getElementById('dvPreview'); if(!box) return;
      var rows=[], idx={{}}, minW=null, maxW=null;
      document.querySelectorAll('.asgForm').forEach(function(f){{
        var role=((f.querySelector('[name=role]')||{{}}).value||'').trim();
        var kind=(f.querySelector('[name=member_kind]')||{{}}).value||'内部';
        var owner=(kind==='外部'?(f.querySelector('[name=owner_txt]')||{{}}).value:(f.querySelector('[name=owner_sel]')||{{}}).value)||'';
        owner=owner.trim();
        var label=owner||('['+(role||'未設定')+'] 未定');
        var fw=_mondayOf((f.querySelector('[name=from_week]')||{{}}).value), tw=_mondayOf((f.querySelector('[name=to_week]')||{{}}).value);
        var a=parseFloat((f.querySelector('[name=fte_pct]')||{{}}).value)||0, b=parseFloat((f.querySelector('[name=fte_billing]')||{{}}).value)||0;
        if(!fw||!tw) return;
        if(minW===null||fw<minW)minW=fw; if(maxW===null||tw>maxW)maxW=tw;
        if(!(label in idx)){{ idx[label]=rows.length; rows.push({{label:label,cells:{{}}}}); }}
        var row=rows[idx[label]]; var w=fw, g=0;
        while(w<=tw && g<520){{ row.cells[w]=row.cells[w]||{{a:0,b:0}}; row.cells[w].a+=a; row.cells[w].b+=b; w=_isoAdd(w,1); g++; }}
      }});
      if(minW===null){{ box.innerHTML='<p class="muted">アサインを入力するとここに週別グリッドが表示されます。</p>'; return; }}
      var weeks=[], w=minW, g=0; while(w<=maxW && g<520){{ weeks.push(w); w=_isoAdd(w,1); g++; }}
      var html='<div style="overflow:auto"><table style="border-collapse:collapse"><tr><th></th>'
        +weeks.map(function(k){{var p=k.split('-');return '<th style="font-size:11px;white-space:nowrap">'+(+p[1])+'/'+(+p[2])+'</th>';}}).join('')+'</tr>';
      rows.forEach(function(r){{
        html+='<tr><th style="text-align:left;white-space:nowrap">'+_esc3(r.label)+'</th>';
        weeks.forEach(function(k){{ var c=r.cells[k];
          if(c&&(c.a||c.b)){{ var sub=(Math.abs((c.b||0)-(c.a||0))>0.01)?'<br><span style="font-size:9px;opacity:.7">請'+_r1(c.b)+'</span>':'';
            html+='<td style="text-align:center;'+_heatJs(c.a)+'">'+_r1(c.a)+'%'+sub+'</td>'; }}
          else {{ html+='<td style="text-align:center;color:#cbd5e1">·</td>'; }} }});
        html+='</tr>';
      }});
      html+='</table></div><p class="muted" style="font-size:11px;margin:6px 0 0">※色は実想定基準。請求が異なる週は「請◯」併記。編集に追従（行＝メンバー、未選択は役割）。全社の総工数はHishoで。</p>';
      box.innerHTML=html;
    }}
    // 責任者・担当者は下の「アサイン」各行のチェックボックスから指定する（2026-08-29改訂。
    // 従来はここで直接セレクトしていたが、アサイン行と紐づけて入力したいという要望に対応）。
    // ここは自動表示のみ。チェック状態が変わるたびに、その行の現在のメンバー名をサーバへ即保存する
    // （値が前回送信時から変わった時だけfetchする＝キー入力のたびに無駄打ちしないためのdedupe）。
    var _dvLastResp={_json.dumps(dv.get("responsible_owner") or "")}, _dvLastHandle={_json.dumps(dv.get("handling_owner") or "")};
    function _dvRowOwner(row){{
      var kind=(row.querySelector('[name=member_kind]')||{{}}).value||'内部';
      var v=(kind==='外部'?(row.querySelector('[name=owner_txt]')||{{}}).value:(row.querySelector('[name=owner_sel]')||{{}}).value)||'';
      return v.trim();
    }}
    function dvOwnerRolesRender(){{
      var box=document.getElementById('dvOwnerRolesBox'); if(!box) return;
      var resp='', handle='';
      document.querySelectorAll('.asgForm').forEach(function(row){{
        var rcb=row.querySelector('input[data-role-field=responsible_owner]');
        var hcb=row.querySelector('input[data-role-field=handling_owner]');
        if(rcb && rcb.checked) resp=_dvRowOwner(row);
        if(hcb && hcb.checked) handle=_dvRowOwner(row);
      }});
      box.innerHTML =
        '<div style="font-size:12px;margin-bottom:2px">責任者: <b>'+(resp?_esc3(resp):'<span class="muted">未設定</span>')+'</b></div>'
        +'<div style="font-size:12px">担当者: <b>'+(handle?_esc3(handle):'<span class="muted">未設定</span>')+'</b></div>';
      if(resp!==_dvLastResp){{ _dvLastResp=resp;
        fetch('/delivery/{delivery_id}/field',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
          body:'field=responsible_owner&value='+encodeURIComponent(resp)}}).catch(function(){{}}); }}
      if(handle!==_dvLastHandle){{ _dvLastHandle=handle;
        fetch('/delivery/{delivery_id}/field',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},
          body:'field=handling_owner&value='+encodeURIComponent(handle)}}).catch(function(){{}}); }}
    }}
    // 責任者/担当者チェックボックスはそれぞれ1行のみ選べる（同じfieldの他行を自動でオフにする）。
    function dvOwnerRoleToggle(field, cb){{
      if(cb.checked){{
        document.querySelectorAll('.asgForm input[data-role-field="'+field+'"]').forEach(function(other){{
          if(other!==cb) other.checked=false;
        }});
      }}
      dvOwnerRolesRender();
    }}
    function recompute(){{ checkRoleTotals(); renderPreview(); dvOwnerRolesRender(); }}
    // 基礎情報フォーム(#dvBaseForm)は入力の都度バックグラウンドで自動保存する（保存ボタン押し忘れ対策・
    // ユーザー報告2026-08-29：基礎情報を保存しないまま他項目を触ると入力内容が消える）。
    var _dvBaseSaveTimer=null;
    function dvBaseAutoSave(reload){{
      var form=document.getElementById('dvBaseForm'); if(!form) return;
      var st=document.getElementById('dvBaseSaveStatus');
      if(st){{ st.textContent='保存中…'; st.style.color='#94a3b8'; }}
      var body=new URLSearchParams(new FormData(form)); body.set('ajax','1');
      fetch(form.action,{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}})
        .then(function(r){{
          if(reload){{ location.reload(); return; }}
          if(st){{ st.textContent=r.ok?'自動保存済み':'保存失敗'; st.style.color=r.ok?'#059669':'#b91c1c'; }}
        }})
        .catch(function(){{ if(st){{ st.textContent='保存失敗（通信エラー）'; st.style.color='#b91c1c'; }} }});
    }}
    document.addEventListener('DOMContentLoaded',function(){{
      document.querySelectorAll('.wkdate').forEach(function(el){{el.addEventListener('change',function(){{snapWk(el);}});}});
      document.querySelectorAll('.mkind').forEach(function(s){{tglMember(s);}});
      // 入力（rate/role/target/メンバー/期間）で整合＋プレビューをライブ更新
      document.querySelectorAll('.asgForm [name=fte_pct],.asgForm [name=fte_billing],.asgForm [name=role],'
        +'.asgForm [name=from_week],.asgForm [name=to_week],.asgForm [name=owner_sel],'
        +'.asgForm [name=owner_txt],.asgForm [name=member_kind],'
        +'.roleRow .rRole,.roleRow .rTgtB,.roleRow .rTgtA').forEach(function(i){{
        i.addEventListener('input',recompute); i.addEventListener('change',recompute);}});
      // 自動保存: 各アサイン行・体制行の変更でajax保存（保存ボタン不要）
      document.querySelectorAll('.asgForm,.roleRow').forEach(function(form){{
        form.addEventListener('change',function(){{autoSave(form);}});
      }});
      initRoleDrag({delivery_id});
      // 基礎情報: フォーム内の項目変更で自動保存（責任者/担当者selectはform属性経由でも拾う）
      document.addEventListener('change',function(e){{
        var el=e.target;
        if(el.form && el.form.id==='dvBaseForm'){{
          if(el.id==='hdrWeeks'){{
            // 週数はDB列を持たない表示専用フィールド（開始週から逆算した終了週を
            // hdrCalcEnd()が計算するだけ）。開始週が未入力だとhdrCalcEnd()は何もせず
            // end_weekが空のまま自動保存→即時reloadされ、せっかく入力した週数が
            // どこにも保存されずに画面から消えてしまっていた（ユーザー報告2026-09-03）。
            // 開始週が入力済みで実際にend_weekが計算できた時だけ保存・再読込する。
            if(!(document.getElementById('hdrStart')||{{}}).value) return;
            dvBaseAutoSave(true);
            return;
          }}
          // 開始/終了週は週数の連動再計算、事業種別L1は事業種別L2の選択肢のサーバ側
          // 再計算のため、保存後に再読込して画面を最新化する。それ以外は再読込不要。
          var reload=(el.name==='start_week'||el.name==='end_week'
            ||el.name==='business_type_l1_override');
          dvBaseAutoSave(reload);
        }}
      }});
      recompute();
    }});
    </script>"""


def base_workload_page(con) -> str:
    """ベース工数（人×機能×%）の編集。#75。SFA正本。
    マスタの全メンバーを（マスタ順で）常に表示。未入力の人は空欄（＝ベース0%）のまま。"""
    _owners_ord = sfa_db.get_master_list(con, "owners") or list(sfa_db.OWNERS)
    by_owner_rows: dict = {}
    for r in sfa_db.list_base_workload(con):
        by_owner_rows.setdefault(r["owner"], []).append(r)
    by_owner_sum = sfa_db.base_workload_by_owner(con)
    _base_max = sfa_db.get_owner_base_max(con)
    _bmp = sfa_db.list_base_max_periods(con)
    # マスタ外にベースを持つ人（旧データ等）も末尾に出す
    extra = [o for o in by_owner_rows if o not in set(_owners_ord)]
    order = _owners_ord + sorted(extra)

    SLOTS = 5
    MAX_PERIODS = 3
    blocks = ""
    for o in order:
        rws = by_owner_rows.get(o, [])
        tot = by_owner_sum.get(o, 0)
        cells = ""
        for i in range(SLOTS):
            r = rws[i] if i < len(rws) else None
            fn = _esc(r["function"]) if r else ""
            pc = _num_pct(r["pct"]) if r else ""
            cells += (
                f'<span style="display:inline-flex;gap:3px;align-items:center;margin:0 6px 4px 0">'
                f'<input type="text" name="function" value="{fn}" placeholder="機能{i+1}" class="bwFn" style="width:120px;font-size:12px">'
                f'<input type="number" name="pct" min="0" max="200" step="5" value="{pc}" placeholder="%" class="bwPct" style="width:56px;font-size:12px">'
                f'<button type="button" class="btn sec" style="font-size:11px;color:#c53030;padding:2px 6px" '
                f'onclick="bwClear(this)" title="この項目をクリア">×</button></span>')
        # ベース最大稼働率の期間編集（開始週/終了週/最大%）×MAX_PERIODS。既存期間を前詰め、無ければ単一値を1行目に。
        _ps = list(_bmp.get(o) or [])
        if not _ps and o in _base_max:
            _ps = [{"from_week": "", "to_week": "", "max_pct": _base_max[o]}]
        mx_rows = ""
        for i in range(MAX_PERIODS):
            _p = _ps[i] if i < len(_ps) else {"from_week": "", "to_week": "", "max_pct": ""}
            _mv = _num_pct(_p["max_pct"]) if (_p.get("max_pct") not in (None, "")) else ""
            mx_rows += (
                f'<div style="display:flex;gap:5px;align-items:center;margin:2px 0;font-size:11px">'
                f'<input type="date" name="from_week" value="{_esc(_p.get("from_week") or "")}" class="bmFrom" style="font-size:11px" title="開始週(月曜)">'
                f'<span class="muted">〜</span>'
                f'<input type="date" name="to_week" value="{_esc(_p.get("to_week") or "")}" class="bmTo" style="font-size:11px" title="終了週(空=以降継続)">'
                f'<input type="number" name="max_pct" min="0" max="100" step="5" value="{_mv}" class="bmMax" placeholder="%" style="width:58px;font-size:11px" title="最大稼働率%">%'
                f'</div>')
        max_form = (
            f'<form class="bwMaxForm" method="post" action="/base-workload/save-max-periods" data-owner="{_esc(o)}" '
            f'style="border-top:1px dashed #eef1f6;margin-top:6px;padding-top:6px">'
            f'<input type="hidden" name="owner" value="{_esc(o)}">'
            f'<div style="font-size:11px;color:#475569;margin-bottom:2px">ベース最大稼働率（期間別・InProcに割ける最大%）'
            f'<span class="muted" style="font-size:10px">　終了週は空＝以降ずっと。未来へ追加（過去は原則編集しない）</span>'
            f'<span class="bwMaxSaved" style="font-size:10px;color:#94a3b8;margin-left:6px"></span></div>'
            f'{mx_rows}<div class="bwGap" style="font-size:11px;color:#c53030;margin-top:2px"></div></form>')
        blocks += (
            f'<div style="border:1px solid #eef1f6;border-radius:8px;padding:8px 10px;margin-bottom:6px">'
            f'<form class="bwForm" method="post" action="/base-workload/save-slots" data-owner="{_esc(o)}">'
            f'<input type="hidden" name="owner" value="{_esc(o)}">'
            f'<div style="font-size:12px;margin-bottom:4px;display:flex;gap:12px;align-items:center;flex-wrap:wrap"><b>{_esc(o)}</b> '
            f'<span class="muted">合計 <span class="bwSum">{_num_pct(tot)}</span>%</span>'
            f'<span class="bwSaved" style="font-size:10px;color:#94a3b8"></span></div>'
            f'{cells}</form>{max_form}</div>')
    return f"""
    <div class="card">
      <p style="margin:0 0 8px"><a href="/deliveries">← Delivery一覧</a></p>
      <h2 style="margin:0 0 4px">ベース工数（恒常稼働：人 × 機能 × %）</h2>
      <p class="muted" style="margin:0 0 12px">案件に紐づかない恒常的な稼働（営業・管理・採用など）を人ごとに最大{SLOTS}項目まで登録。工数は合計されます。
        マスタの全員を表示・未入力はベース0%。<b>入力すると自動保存</b>（保存ボタンなし）。「×」でその項目をクリア。
        Hishoの総工数（デモ開発＋Delivery＋<b>ベース</b>）に加算されます。例: 早瀬 営業 30%。<br>
        <b>ベース最大稼働率</b>は期間別に設定でき（開始週/終了週/最大%）、稼働予定の負荷率(色)の分母になります。期間の間に空きがあると⚠表示。</p>
      <div style="overflow:auto">{blocks}</div>
    </div>
    <script>
    function _bwRecalc(form){{
      var s=0; form.querySelectorAll('.bwPct').forEach(function(i){{ var v=parseFloat(i.value); if(!isNaN(v)) s+=v; }});
      var el=form.querySelector('.bwSum'); if(el) el.textContent=(Math.round(s*10)/10);
    }}
    function _bwSave(form){{
      _bwRecalc(form);
      var st=form.querySelector('.bwSaved'); if(st){{st.textContent='保存中…';st.style.color='#94a3b8';}}
      var body=new URLSearchParams(new FormData(form)); body.set('ajax','1');
      fetch(form.action,{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}})
        .then(function(r){{ if(st){{st.textContent=r.ok?'保存済み':'保存失敗';st.style.color=r.ok?'#059669':'#b91c1c';}} }})
        .catch(function(){{ if(st){{st.textContent='保存失敗';st.style.color='#b91c1c';}} }});
    }}
    function _bwPack(form){{ // 非空の項目を左詰め（クリア後の並べ直し）
      var fns=form.querySelectorAll('.bwFn'), pcs=form.querySelectorAll('.bwPct'), pairs=[];
      for(var i=0;i<fns.length;i++){{ if(fns[i].value.trim()) pairs.push([fns[i].value, pcs[i]?pcs[i].value:'']); }}
      for(var j=0;j<fns.length;j++){{ if(j<pairs.length){{ fns[j].value=pairs[j][0]; pcs[j].value=pairs[j][1]; }}
        else {{ fns[j].value=''; pcs[j].value=''; }} }}
    }}
    function bwClear(btn){{ var sp=btn.parentElement;
      sp.querySelectorAll('input').forEach(function(i){{ i.value=''; }});
      var form=btn.closest('.bwForm'); if(form){{ _bwPack(form); _bwSave(form); }} }}
    // 期間フォーム: 保存＋期間の隙間チェック（⚠）
    function _bmSave(form){{
      var st=form.querySelector('.bwMaxSaved'); if(st){{st.textContent='保存中…';st.style.color='#94a3b8';}}
      var body=new URLSearchParams(new FormData(form)); body.set('ajax','1');
      fetch(form.action,{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:body.toString()}})
        .then(function(r){{ if(st){{st.textContent=r.ok?'保存済み':'保存失敗';st.style.color=r.ok?'#059669':'#b91c1c';}} }})
        .catch(function(){{ if(st){{st.textContent='保存失敗';st.style.color='#b91c1c';}} }});
    }}
    function _bmGap(form){{
      var fs=form.querySelectorAll('.bmFrom'), ts=form.querySelectorAll('.bmTo'), ms=form.querySelectorAll('.bmMax');
      var ps=[];
      for(var i=0;i<fs.length;i++){{ var fw=fs[i].value, tw=ts[i].value, mx=ms[i]?ms[i].value:'';
        if(fw||tw||mx) ps.push({{f:fw,t:tw}}); }}
      ps.sort(function(a,b){{ if(!a.f&&b.f)return -1; if(a.f&&!b.f)return 1; return a.f<b.f?-1:(a.f>b.f?1:0); }});
      var msgs=[];
      for(var j=0;j+1<ps.length;j++){{ var cur=ps[j], nxt=ps[j+1];
        if(!cur.t){{ msgs.push((cur.f||'(開始未定)')+'は終了なし(継続)なのに後続の期間があります'); continue; }}
        if(!nxt.f){{ continue; }}
        var d=new Date(cur.t); d.setDate(d.getDate()+7); var expect=d.toISOString().slice(0,10);
        if(nxt.f>expect){{ msgs.push(cur.t+'の翌週〜'+nxt.f+'の手前に空き期間があります'); }}
        else if(nxt.f<=cur.t){{ msgs.push('期間が重複('+cur.t+' と '+nxt.f+')'); }}
      }}
      var el=form.querySelector('.bwGap'); if(el) el.textContent = msgs.length ? ('⚠ '+msgs.join(' / ')) : '';
    }}
    document.addEventListener('DOMContentLoaded',function(){{
      document.querySelectorAll('.bwForm').forEach(function(form){{
        form.addEventListener('change',function(){{ _bwSave(form); }});
        form.querySelectorAll('.bwPct').forEach(function(i){{ i.addEventListener('input',function(){{ _bwRecalc(form); }}); }});
      }});
      document.querySelectorAll('.bwMaxForm').forEach(function(form){{
        _bmGap(form);
        form.addEventListener('change',function(){{ _bmGap(form); _bmSave(form); }});
      }});
    }});
    </script>"""


# ── メールパターン管理 ───────────────────────────────────────────────────────────

