# 【共有コンポーネント】文字起こしの取り込み（貼付＋ファイルアップロード）
# すべてのヒアリング/議論サマリ整形機能で共通利用する。取り込み仕様の変更（対応拡張子の追加・
# パース方法・UI等）は必ずここ（_transcript_intake_form / _resolve_transcript_input /
# _extract_uploaded_transcript）を更新すること。1箇所直せば全整形機能（商談ヒアリング・論点・
# 今後追加分）へ一括反映される前提を維持する。関連: OneNoteメモの _RICH_NOTE_ASSETS と同方針。
# ══════════════════════════════════════════════════════════════════════════════

# 取り込み対応拡張子（UIの accept 属性とサーバ側パースの両方で参照する単一の真実）
TRANSCRIPT_UPLOAD_EXTS = ("txt", "text", "md", "markdown", "vtt", "srt", "docx")


def _strip_subtitle_cues(text: str) -> str:
    """字幕(.vtt/.srt)のヘッダ・キュー番号・タイムスタンプ行を除去して発話本文だけ残す。"""
    out = []
    for ln in (text or "").splitlines():
        s = ln.strip()
        if not s:
            continue
        if s.upper().startswith("WEBVTT"):
            continue
        if "-->" in s:               # タイムスタンプ行
            continue
        if s.isdigit():              # SRTのキュー番号
            continue
        out.append(s)
    return "\n".join(out)


def _extract_uploaded_transcript(upload) -> str:
    """アップロードされた (filename, bytes) から文字起こしテキストを抽出する。共有コンポーネント。
    .docx はpython-docxで段落＋表を抽出、テキスト系は UTF-8→CP932 の順にデコード。失敗時は空文字。"""
    if not (isinstance(upload, tuple) and len(upload) == 2):
        return ""
    filename, data = upload
    if not data:
        return ""
    ext = (filename or "").rsplit(".", 1)[-1].lower() if "." in (filename or "") else ""
    if ext == "docx":
        try:
            import io
            from docx import Document
            doc = Document(io.BytesIO(data))
            lines = [p.text for p in doc.paragraphs]
            for tbl in doc.tables:
                for row in tbl.rows:
                    cells = [c.text.strip() for c in row.cells]
                    if any(cells):
                        lines.append("\t".join(cells))
            return "\n".join(lines).strip()
        except Exception as _e:
            print(f"[transcript/docx] parse error: {_e}", flush=True)
            return ""
    # テキスト系（.txt/.md/.vtt/.srt など、拡張子不明でもテキストとして試行）
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        try:
            text = data.decode("cp932")   # Windows日本語(Shift_JIS系)
        except Exception:
            text = data.decode("utf-8", errors="replace")
    if ext in ("vtt", "srt"):
        text = _strip_subtitle_cues(text)
    return text.strip()


def _resolve_transcript_input(f) -> str:
    """取り込みフォームの入力から文字起こし本文を取り出す（アップロードファイル優先→貼付）。
    共有コンポーネント。全整形ルート（/hearing/intake/structure, /deal-issue/*/intake/structure 等）
    から共通で呼ぶ。フォームは multipart 前提（_form_multi でファイルは (filename, bytes) で届く）。"""
    from_file = _extract_uploaded_transcript(f.get("transcript_file")) if isinstance(f, dict) else ""
    if from_file.strip():
        return from_file.strip()
    return (f.get("transcript") or "").strip()


def _transcript_intake_form(*, action: str, cancel_href: str, inner_fields_html: str = "",
                            submit_label: str = "🤖 AIで整形する") -> str:
    """文字起こし取り込みフォーム（貼付＋ファイルアップロード）の共有UI。全整形機能で共通利用する。
    inner_fields_html には各機能固有の隠しフィールド/選択欄を渡す（フォーム冒頭に差し込む）。"""
    accept = ",".join("." + e for e in TRANSCRIPT_UPLOAD_EXTS)
    # 送信後はAI整形に数十秒かかることがあるため、ボタンを「整形中…」表示にして二重送信を防ぐ（体感の“固まり”対策）。
    _onsubmit = ("var b=this.querySelector('button[type=submit]');"
                 "setTimeout(function(){if(b){b.disabled=true;b.dataset.busy='1';"
                 "b.textContent='🤖 AI整形中…（最大1分ほどお待ちください）';}},0);return true;")
    return f"""
      <form method="post" action="{action}" enctype="multipart/form-data" onsubmit="{_onsubmit}">
        {inner_fields_html}
        <div class="filter-row js-nofilter" style="margin:6px 0 2px;gap:10px;align-items:center;flex-wrap:wrap">
          <label style="font-size:13px">📎 ファイルから取り込み
            <input type="file" name="transcript_file" accept="{accept}" style="font-size:12px"></label>
        </div>
        <p class="muted" style="font-size:11px;margin:0 0 6px">対応: .txt / .md / .vtt / .srt / .docx（Word）。
          ファイルを選ぶと貼付欄より優先します。</p>
        <textarea name="transcript" rows="16" placeholder="ここに文字起こしを貼り付け…（またはファイルを選択）"
          style="width:100%;box-sizing:border-box;font-size:13px;padding:8px;line-height:1.6"></textarea>
        <div style="margin-top:10px;display:flex;gap:8px">
          <button class="btn" type="submit">{submit_label}</button>
          <a class="btn sec" href="{cancel_href}">キャンセル</a>
        </div>
        <p class="muted" style="font-size:11px;margin-top:6px">※ 整形はClaude(Haiku)で実行。長い文字起こしは先頭約12,000文字を対象にします。</p>
      </form>"""


def _intake_ai_warn_html(ai_ok: bool) -> str:
    """整形結果の確認画面で出す警告（共有）。キー未設定と呼び出し失敗を区別して原因を明示する。"""
    if ai_ok:
        return ""
    if not ANTHROPIC_API_KEY:
        msg = ("AIキー（ANTHROPIC_API_KEY）が未設定のため自動整形は行われませんでした。手動で編集して確定できます。"
               "／管理者へ: Render(sfa-crm)の環境変数 ANTHROPIC_API_KEY を設定してください。")
    else:
        msg = "AI整形に失敗しました（タイムアウト／応答の解析失敗等）。手動で編集して確定できます。"
    return ('<div style="background:#fef2f2;border-left:3px solid #dc2626;padding:6px 10px;'
            'margin:6px 0;font-size:12px;color:#991b1b">⚠ ' + msg + '</div>')


def _intake_originals_html(con, kind: str, entity_id: int, back_url: str) -> str:
    """取り込み原本（文字起こしローデータ＋アップロード原本ファイル）の一覧セクション。論点・商談で共通。
    無ければ空文字。本文表示 /intake-transcript/{id}/view・原本DL /…/file・削除 /…/delete を提供する。"""
    intakes = sfa_db.list_intake_transcripts(con, kind, entity_id)
    if not intakes:
        return ""

    def _fkb(n):
        return f"{round((n or 0) / 1024):,}KB" if n else ""

    def _usage_html(t):
        usages = sfa_db.find_intake_transcript_usages(con, t["id"])
        if not usages:
            return ''
        links = []
        for u in usages:
            if u["type"] == "rich_note":
                links.append(f'<a href="javascript:void(0)" onclick="rnOpen(\'{kind}\',{entity_id},{u["id"]})" '
                            f'style="font-size:11px">{_esc(u["label"])}</a>')
            elif u["type"] == "hearing_result":
                links.append(f'<a href="/hearing/result/{u["id"]}" style="font-size:11px">{_esc(u["label"])}</a>')
            else:
                links.append(f'<a href="/deal/{entity_id}#act-{u["id"]}" style="font-size:11px">{_esc(u["label"])}</a>')
        return ('<div class="muted" style="font-size:11px;margin-top:2px">→ 使用済み: '
                + '　'.join(links) + '</div>')

    rows = "".join(
        '<div style="display:flex;flex-direction:column;gap:2px;padding:6px 8px;border:1px solid #e2e8f0;'
        'border-radius:8px;background:#fff;font-size:12px">'
        '<div style="display:flex;align-items:center;gap:8px">'
        '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'
        f'{"📎 " if t.get("source") == "file" else "📝 "}{_esc(t.get("filename") or "貼り付けテキスト")}'
        f'<span class="muted"> ・ {_esc((t.get("created_at") or "")[:16])}'
        f'{(" ・ " + _fkb(t.get("file_size"))) if t.get("file_size") else ""}</span></span>'
        f'<a class="btn sec" style="font-size:11px;padding:2px 8px" href="/intake-transcript/{t["id"]}/view" '
        f'target="_blank" title="文字起こし本文を表示">本文</a>'
        + (f'<a class="btn sec" style="font-size:11px;padding:2px 8px" href="/intake-transcript/{t["id"]}/file" '
           f'title="原本ファイルをダウンロード">原本DL</a>' if t.get("file_size") else "")
        + f'<form method="post" action="/intake-transcript/{t["id"]}/delete" style="margin:0" '
          f'onsubmit="return confirm(\'この取り込み原本を削除しますか？\')">'
          f'<input type="hidden" name="return_to" value="{_esc(back_url)}">'
          f'<button type="submit" class="muted" style="background:none;border:0;cursor:pointer;font-size:12px" '
          f'title="削除">✕</button></form>'
        '</div>'
        + _usage_html(t)
        + '</div>'
        for t in intakes
    )
    return (
        '<div style="border-top:1px solid #eef1f5;padding-top:12px;margin-top:14px">'
        '<h2 style="margin:0 0 8px">🎙️ 取り込み原本（文字起こし）</h2>'
        '<div style="display:flex;flex-direction:column;gap:6px">' + rows + '</div></div>'
    )


